insert into public.cuisine_meals
  (country_id, name, name_tr, city, city_tr, description, description_tr, image_url, sort_order)
values
('716', 'Sadza', 'Sadza', null, null, 'A thick maize-meal porridge that is Zimbabwe''s everyday staple, eaten with a stew or vegetables.', 'Zimbabve''nin günlük temel besini olan, genellikle bir yahni veya sebzeyle yenen kalın mısır ununden yapılan lapa.', '', 1),
('716', 'Sadza ne Nyama', 'Sadza ne Nyama', null, null, 'Sadza served with a rich meat stew, usually beef or chicken in gravy.', 'Genellikle sığır eti veya tavuklu bir sosla servis edilen sadza.', '', 2),
('716', 'Dovi', 'Dovi', null, null, 'A peanut butter stew cooked with chicken or vegetables and leafy greens.', 'Tavuk veya sebze ve yeşilliklerle pişirilen fıstık ezmeli bir yahni.', '', 3),
('716', 'Muriwo unedovi', 'Muriwo unedovi', null, null, 'Collard greens or spinach cooked in a creamy peanut butter sauce.', 'Kremamsı fıstık ezmesi sosunda pişirilen kıvırcık lahana veya ıspanak.', '', 4),
('716', 'Bota', 'Bota', null, null, 'A thin, smooth maize or millet porridge eaten for breakfast, often sweetened or flavored with peanut butter.', 'Kahvaltıda yenen, genellikle tatlandırılmış veya fıstık ezmesiyle lezzetlendirilmiş ince mısır veya darı lapası.', '', 5),
('716', 'Madora (Mopane Worms)', 'Madora (Mopane Kurtları)', null, null, 'Dried and fried mopane caterpillars, a protein-rich delicacy often cooked with tomatoes and onions.', 'Genellikle domates ve soğanla pişirilen, protein açısından zengin kurutulmuş ve kızartılmış mopane tırtılları.', '', 6),
('894', 'Nshima', 'Nshima', null, null, 'A stiff porridge made from maize meal that forms the staple starch of Zambian meals.', 'Zambiya yemeklerinin temel nişastasını oluşturan mısır ununden yapılan sert bir lapa.', '', 1),
('894', 'Ifisashi', 'Ifisashi', null, null, 'Vegetables such as pumpkin leaves or spinach stewed in a creamy ground peanut sauce.', 'Balkabağı yaprakları veya ıspanak gibi sebzelerin kremamsı çekilmiş fıstık sosunda pişirilmesiyle yapılır.', '', 2),
('894', 'Chikanda', 'Chikanda', null, null, 'A firm loaf made from wild orchid tubers mixed with ground peanuts, known as African polony.', 'Yabani orkide yumrularının çekilmiş fıstıkla karıştırılmasıyla yapılan, Afrika sosisi olarak bilinen sıkı bir kek.', '', 3),
('894', 'Kapenta', 'Kapenta', null, null, 'Small dried or fresh sardine-like fish, usually fried or stewed with tomatoes and onions.', 'Genellikle domates ve soğanla kızartılan veya haşlanan küçük kurutulmuş veya taze sardalya benzeri balık.', '', 4),
('894', 'Village Chicken (Inkoko ya Mumushi)', 'Köy Tavuğu (Inkoko ya Mumushi)', null, null, 'Free-range chicken slow-cooked in a simple stew, prized for its firmer texture and flavor.', 'Daha sert dokusu ve lezzetiyle bilinen, serbest gezen tavuğun basit bir yahnide yavaşça pişirilmesiyle yapılır.', '', 5),
('887', 'Saltah', 'Selta', null, null, 'A bubbling meat and vegetable stew topped with a frothy fenugreek foam called hulba.', 'Üzerine hulba adı verilen köpüklü çemen otu köpüğü eklenen, fokurdayan et ve sebze yahnisi.', '', 1),
('887', 'Mandi', 'Mandi', 'Hadhramaut', 'Hadramut', 'Spiced rice slow-cooked with tender lamb or chicken traditionally cooked in an underground pit oven.', 'Geleneksel olarak yer altı çukur fırınında pişirilen, baharatlı pirinç ve yumuşak kuzu veya tavuk eti.', '', 2),
('887', 'Fahsa', 'Fahsa', null, null, 'A spicy shredded meat stew often served bubbling hot in a stone pot with bread.', 'Genellikle taş bir kapta fokurdayarak sıcak servis edilen, baharatlı parçalanmış et yahnisi.', '', 3),
('887', 'Bint Al-Sahn', 'Bint Al-Sahn', null, null, 'A layered honey cake made of flaky buttered dough, often topped with nigella seeds.', 'Genellikle çörek otu ile süslenen, tereyağlı katmerli hamurdan yapılan katmanlı bal keki.', '', 4),
('887', 'Zurbian', 'Zürbiyan', null, null, 'A spiced rice dish layered with marinated meat, similar to biryani, cooked together until fragrant.', 'Marine edilmiş etle katmanlanmış, biryaniye benzer, kokulu olana kadar birlikte pişirilen baharatlı pirinç yemeği.', '', 5),
('887', 'Shafoot', 'Şafut', null, null, 'Thin fermented flatbread soaked in spiced yogurt and topped with fresh herbs and vegetables.', 'Baharatlı yoğurda batırılan ve taze otlar ile sebzelerle süslenen ince mayalı yassı ekmek.', '', 6),
('704', 'Pho', 'Pho', 'Hanoi', 'Hanoi', 'A fragrant noodle soup made with a long-simmered beef or chicken broth, rice noodles, and herbs.', 'Uzun süre kaynatılmış sığır eti veya tavuk suyu, pirinç eriştesi ve otlarla yapılan kokulu bir çorba.', '', 1),
('704', 'Bun Cha', 'Bun Cha', 'Hanoi', 'Hanoi', 'Grilled pork patties and slices served in a sweet-savory dipping broth with rice noodles and herbs.', 'Tatlı-tuzlu bir sosa batırılarak pirinç eriştesi ve otlarla servis edilen ızgara domuz köftesi ve dilimleri.', '', 2),
('704', 'Banh Mi', 'Banh Mi', null, null, 'A crusty baguette sandwich filled with pork, pate, pickled vegetables, cilantro, and chili.', 'Domuz eti, ciğer ezmesi, turşu sebzeler, kişniş ve acı biberle doldurulmuş çıtır baget sandviç.', '', 3),
('704', 'Goi Cuon', 'Goi Cuon', null, null, 'Fresh rice paper rolls filled with shrimp, pork, herbs, and rice vermicelli, served with peanut sauce.', 'Karides, domuz eti, otlar ve pirinç şehriyesiyle doldurulan, fıstık sosuyla servis edilen taze pirinç kağıdı rulosu.', '', 4),
('704', 'Cao Lau', 'Cao Lau', 'Hoi An', 'Hoi An', 'Thick rice noodles with pork, herbs, and crispy croutons, a specialty said to use local well water.', 'Domuz eti, otlar ve çıtır kruton ile yapılan, yerel kuyu suyuyla hazırlandığı söylenen kalın pirinç eriştesi.', '', 5),
('704', 'Bun Bo Hue', 'Bun Bo Hue', 'Hue', 'Hue', 'A spicy and tangy beef and pork noodle soup flavored with lemongrass and shrimp paste.', 'Limon otu ve karides ezmesiyle tatlandırılmış baharatlı ve ekşi sığır ve domuz etli erişte çorbası.', '', 6),
('704', 'Banh Xeo', 'Banh Xeo', null, null, 'A crispy turmeric rice-flour crepe filled with pork, shrimp, and bean sprouts, wrapped in lettuce and herbs.', 'Domuz eti, karides ve fasulye filizi ile doldurulan, marul ve otlarla sarılan çıtır zerdeçallı pirinç unu krepi.', '', 7),
('704', 'Com Tam', 'Com Tam', null, null, 'Broken rice served with grilled pork chop, fried egg, and pickled vegetables.', 'Izgara domuz pirzolası, sahanda yumurta ve turşu sebzelerle servis edilen kırık pirinç.', '', 8),
('704', 'Cha Ca', 'Cha Ca', 'Hanoi', 'Hanoi', 'Turmeric-marinated fish grilled at the table with dill and spring onion, served over rice noodles.', 'Masada dereotu ve taze soğanla ızgara yapılan, pirinç eriştesi üzerinde servis edilen zerdeçallı marine balık.', '', 9),
('704', 'Banh Cuon', 'Banh Cuon', null, null, 'Steamed rice-flour rolls filled with minced pork and mushrooms, served with dipping sauce.', 'Kıyılmış domuz eti ve mantarla doldurulan, sosla servis edilen buharda pişmiş pirinç unu rulosu.', '', 10),
('704', 'Mi Quang', 'Mi Quang', 'Quang Nam', 'Quang Nam', 'Turmeric-tinted noodles in a small amount of rich broth with pork, shrimp, and peanuts.', 'Domuz eti, karides ve fıstıkla, az miktarda zengin et suyunda servis edilen zerdeçallı erişte.', '', 11),
('704', 'Bo Kho', 'Bo Kho', null, null, 'A hearty beef stew simmered with star anise, lemongrass, and carrots, often eaten with bread or noodles.', 'Yıldız anason, limon otu ve havuçla pişirilen, genellikle ekmek veya erişteyle yenen doyurucu sığır eti yahnisi.', '', 12),
('862', 'Arepa', 'Arepa', null, null, 'A grilled or baked cornmeal patty, split open and filled with cheese, meat, or beans.', 'Izgara veya fırınlanmış, ortası açılıp peynir, et veya fasulyeyle doldurulan mısır unu keki.', '', 1),
('862', 'Pabellón Criollo', 'Pabellón Criollo', null, null, 'The national dish combining shredded beef, black beans, white rice, and fried plantain.', 'Parçalanmış sığır eti, siyah fasulye, beyaz pirinç ve kızarmış muzu bir araya getiren ulusal yemek.', '', 2),
('862', 'Cachapa', 'Cachapa', null, null, 'A sweet corn pancake, typically folded around soft white cheese.', 'Genellikle yumuşak beyaz peynirle katlanarak servis edilen tatlı mısır krepi.', '', 3),
('862', 'Hallaca', 'Hallaca', null, null, 'A cornmeal dough filled with a stew of meats, olives, and raisins, wrapped and steamed in banana leaves.', 'Et, zeytin ve kuru üzüm yahnisiyle doldurulan, muz yapraklarına sarılıp buharda pişirilen mısır unu hamuru.', '', 4),
('862', 'Tequeños', 'Tequeños', null, null, 'Crispy fried dough sticks wrapped around a core of white cheese.', 'İçinde beyaz peynir bulunan, kızartılmış çıtır hamur çubukları.', '', 5),
('862', 'Asado Negro', 'Asado Negro', null, null, 'Beef pot roast browned in caramelized sugar and slow-cooked in a dark savory sauce.', 'Karamelize şekerle kızartılıp koyu lezzetli bir sosta yavaşça pişirilen sığır kızartması.', '', 6),
('548', 'Lap Lap', 'Lap Lap', null, null, 'Vanuatu''s national dish: grated root vegetables and coconut milk wrapped in leaves and cooked in an underground oven.', 'Vanuatu''nun ulusal yemeği: rendelenmiş kök sebzeler ve hindistancevizi sütünün yapraklara sarılıp yer altı fırınında pişirilmesiyle yapılır.', '', 1),
('548', 'Tuluk', 'Tuluk', null, null, 'Grated yam or manioc wrapped around meat or fish and baked in leaves.', 'Rendelenmiş yer elması veya manyokun et veya balığın etrafına sarılıp yapraklarda pişirilmesiyle yapılır.', '', 2),
('548', 'Coconut Crab', 'Hindistancevizi Yengeci', null, null, 'A large land crab known for eating coconuts, cooked and prized as a local delicacy.', 'Hindistancevizi yediği bilinen, pişirilip yerel bir lezzet olarak değer gören büyük bir kara yengeci.', '', 3),
('860', 'Plov (Osh)', 'Plov (Oş)', 'Samarkand', 'Semerkant', 'A rice pilaf cooked with meat, carrots, and onions in one pot, considered the national dish.', 'Etin, havucun ve soğanın pirinçle tek bir tencerede pişirilmesiyle yapılan, ulusal yemek sayılan pilav.', '', 1),
('860', 'Shashlik', 'Şaşlık', null, null, 'Skewers of marinated meat, usually lamb or beef, grilled over open coals.', 'Genellikle kuzu veya sığır etinden, marine edilip açık kömür ateşinde pişirilen şişler.', '', 2),
('860', 'Manti', 'Mantı', null, null, 'Steamed dumplings filled with seasoned minced meat and onion.', 'Baharatlı kıyma ve soğanla doldurulan buharda pişmiş mantı.', '', 3),
('860', 'Lagman', 'Lagman', null, null, 'A hand-pulled noodle soup with meat, peppers, and vegetables in a spiced broth.', 'Baharatlı bir et suyunda, elde çekilmiş erişte, et, biber ve sebzelerle yapılan çorba.', '', 4),
('860', 'Samsa', 'Samsa', null, null, 'Baked pastry parcels filled with spiced meat, pumpkin, or onion, often cooked in a tandoor oven.', 'Baharatlı et, balkabağı veya soğanla doldurulan, genellikle tandır fırında pişirilen hamur işi.', '', 5),
('860', 'Non (Tandyr Non)', 'Non (Tandır Ekmeği)', null, null, 'Round leavened bread baked on the walls of a clay tandoor oven, central to every meal.', 'Kil tandır fırınının duvarlarında pişirilen, her öğünün merkezinde yer alan yuvarlak mayalı ekmek.', '', 6),
('860', 'Dimlama', 'Dimlama', null, null, 'A layered stew of meat and vegetables slow-cooked in their own juices.', 'Etin ve sebzelerin kendi suyunda yavaşça pişirildiği katmanlı bir yahni.', '', 7),
('858', 'Asado', 'Asado', null, null, 'Slow-grilled beef and other cuts cooked over an open wood or charcoal fire, central to Uruguayan gatherings.', 'Uruguay''da bir araya gelmelerin merkezinde yer alan, açık odun veya kömür ateşinde yavaşça ızgara yapılan sığır eti ve diğer parçalar.', '', 1),
('858', 'Chivito', 'Chivito', null, null, 'A hefty steak sandwich piled with ham, cheese, egg, bacon, and vegetables.', 'Jambon, peynir, yumurta, pastırma ve sebzelerle yüklü büyük bir biftek sandviçi.', '', 2),
('858', 'Milanesa', 'Milanesa', null, null, 'A breaded and fried thin cutlet of beef or chicken, often served with fries or in a sandwich.', 'Genellikle patates kızartmasıyla veya sandviç içinde servis edilen, galeta ununa bulanıp kızartılmış ince sığır veya tavuk pirzolası.', '', 3),
('858', 'Choripán', 'Choripán', null, null, 'A grilled chorizo sausage served in a crusty bread roll, often with chimichurri sauce.', 'Genellikle chimichurri sosuyla, çıtır bir ekmeğin içinde servis edilen ızgara sosis.', '', 4),
('858', 'Morcilla Dulce', 'Tatlı Kan Sosisi', null, null, 'A sweet blood sausage made with orange peel, walnuts, and sometimes fruit, grilled as part of an asado.', 'Portakal kabuğu, ceviz ve bazen meyveyle yapılan, asado sırasında ızgara yapılan tatlı kan sosisi.', '', 5),
('583', 'Breadfruit with Coconut Cream', 'Hindistancevizi Kremalı Ekmek Meyvesi', null, null, 'Roasted or boiled breadfruit served with a rich coconut cream sauce, a staple across Micronesian islands.', 'Mikronezya adalarında yaygın bir temel besin olan, zengin hindistancevizi kreması sosuyla servis edilen közlenmiş veya haşlanmış ekmek meyvesi.', '', 1),
('584', 'Bwiro (Fermented Breadfruit)', 'Bwiro (Fermente Ekmek Meyvesi)', null, null, 'Breadfruit pounded and fermented, then wrapped in leaves and baked, a traditional preserved staple.', 'Dövülüp fermente edilen, ardından yapraklara sarılıp pişirilen ekmek meyvesinden yapılan geleneksel bir saklama yöntemi.', '', 1),
('580', 'Kelaguen', 'Kelaguen', null, null, 'Chopped grilled chicken or beef marinated in lemon juice, hot peppers, and onion, a Chamorro specialty.', 'Limon suyu, acı biber ve soğanla marine edilen, doğranmış ızgara tavuk veya sığır etinden yapılan bir Chamorro yemeği.', '', 1),
('580', 'Chamorro Red Rice', 'Chamorro Kırmızı Pirinci', null, null, 'Rice cooked with annatto seeds, giving it a distinctive red color and earthy flavor.', 'Kendine özgü kırmızı rengini ve toprağımsı tadını veren annatto tohumlarıyla pişirilen pirinç.', '', 2),
('580', 'Tinaktak', 'Tinaktak', null, null, 'Ground beef simmered with coconut milk, green beans, and lemon, a classic Chamorro dish.', 'Hindistancevizi sütü, taze fasulye ve limonla pişirilen kıyma, klasik bir Chamorro yemeği.', '', 3),
('850', 'Fungi', 'Fungi', null, null, 'A cornmeal side dish, often studded with okra, traditionally paired with fish stew.', 'Genellikle bamya ile hazırlanan, geleneksel olarak balık yahnisiyle eşleştirilen mısır unu garnitürü.', '', 1),
('850', 'Callaloo', 'Callaloo', null, null, 'A leafy green stew made with taro or dasheen leaves, okra, and often crab or salted meat.', 'Taro veya dasheen yaprakları, bamya ve genellikle yengeç veya tuzlanmış etle yapılan yeşillikli bir yahni.', '', 2),
('850', 'Conch Fritters', 'Deniz Salyangozu Kroketi', null, null, 'Deep-fried patties of chopped conch meat mixed with peppers and batter.', 'Doğranmış deniz salyangozu eti, biber ve hamurun karıştırılıp kızartılmasıyla yapılan köfteler.', '', 3),
('850', 'Johnnycake', 'Johnnycake', null, null, 'A fried or baked cornmeal flatbread, a common breakfast side across the Caribbean.', 'Karayipler genelinde yaygın bir kahvaltı garnitürü olan, kızartılmış veya fırınlanmış mısır unu ekmeği.', '', 4),
('316', 'Kelaguen', 'Kelaguen', null, null, 'Chopped grilled meat or seafood marinated in lemon juice, hot peppers, and onion.', 'Limon suyu, acı biber ve soğanla marine edilen doğranmış ızgara et veya deniz ürünü.', '', 1),
('316', 'Chamorro Red Rice', 'Chamorro Kırmızı Pirinci', null, null, 'Rice cooked with annatto seeds for a red hue, served at nearly every Chamorro gathering.', 'Kırmızı bir renk için annatto tohumlarıyla pişirilen, neredeyse her Chamorro toplantısında servis edilen pirinç.', '', 2),
('316', 'Kadon Pika', 'Kadon Pika', null, null, 'A spicy stew of meat or seafood cooked with coconut milk and hot peppers.', 'Hindistancevizi sütü ve acı biberle pişirilen baharatlı et veya deniz ürünü yahnisi.', '', 3),
('316', 'Tinaktak', 'Tinaktak', null, null, 'Ground beef simmered in coconut milk with green beans and lemon juice.', 'Hindistancevizi sütünde taze fasulye ve limon suyuyla pişirilen kıyma.', '', 4),
('316', 'Titiyas', 'Titiyas', null, null, 'Thick Chamorro-style flour or corn tortillas cooked on a griddle.', 'Sacda pişirilen kalın Chamorro usulü un veya mısır tortillası.', '', 5),
('016', 'Palusami', 'Palusami', null, null, 'Young taro leaves baked with coconut cream, often with onion, a staple Samoan dish.', 'Genellikle soğanla, hindistancevizi kremasıyla pişirilen genç taro yaprakları, temel bir Samoa yemeği.', '', 1),
('016', 'Oka', 'Oka', null, null, 'Raw fish marinated in lime or lemon juice with coconut cream, onion, and tomato.', 'Hindistancevizi kreması, soğan ve domatesle, misket limonu veya limon suyunda marine edilen çiğ balık.', '', 2),
('016', 'Sapasui', 'Sapasui', null, null, 'A Samoan take on chop suey, with noodles, meat, and vegetables stir-fried together.', 'Erişte, et ve sebzelerin birlikte soteleneceği, çin usulü karışık kızartmanın Samoa yorumu.', '', 3),
('630', 'Mofongo', 'Mofongo', null, null, 'Mashed fried green plantains mixed with garlic and pork cracklings, often shaped into a mound.', 'Sarımsak ve domuz gevreğiyle karıştırılan, ezilmiş kızarmış yeşil muz, genellikle tepe şeklinde servis edilir.', '', 1),
('630', 'Arroz con Gandules', 'Arroz con Gandules', null, null, 'Rice cooked with pigeon peas, sofrito, and often pork, considered Puerto Rico''s signature dish.', 'Güvercin bezelyesi, sofrito ve genellikle domuz etiyle pişirilen, Porto Riko''nun amblem yemeği sayılan pirinç.', '', 2),
('630', 'Lechón', 'Lechón', null, null, 'A whole pig slow-roasted over charcoal until the skin turns crackling crisp.', 'Derisi çıtır çıtır olana kadar kömür üzerinde yavaşça kızartılan bütün domuz.', '', 3),
('630', 'Tostones', 'Tostones', null, null, 'Twice-fried green plantain slices, flattened and crisped, served as a side.', 'İki kez kızartılan, bastırılıp çıtırlaştırılan yeşil muz dilimleri, garnitür olarak servis edilir.', '', 4),
('630', 'Pasteles', 'Pasteles', null, null, 'A masa of grated green banana and root vegetables filled with meat, wrapped in banana leaves and boiled.', 'Etle doldurulan, muz yapraklarına sarılıp haşlanan, rendelenmiş yeşil muz ve kök sebzelerden yapılan hamur.', '', 5),
('630', 'Alcapurria', 'Alcapurria', null, null, 'A fried fritter of grated green banana and taro filled with seasoned meat.', 'Baharatlı etle doldurulan, rendelenmiş yeşil muz ve tarodan yapılan kızarmış mücver.', '', 6),
('630', 'Sancocho', 'Sancocho', null, null, 'A hearty stew of root vegetables, corn, and meat simmered together.', 'Kök sebzeler, mısır ve etin birlikte pişirildiği doyurucu bir yahni.', '', 7),
('840', 'Hamburger', 'Hamburger', null, null, 'A grilled beef patty served in a bun, often with cheese, lettuce, and condiments.', 'Genellikle peynir, marul ve soslarla, bir ekmek arasında servis edilen ızgara sığır köftesi.', '', 1),
('840', 'Barbecue Ribs', 'Barbekü Pirzola', null, null, 'Pork or beef ribs slow-cooked with smoke and basted in a tangy barbecue sauce.', 'Dumanla yavaşça pişirilen ve ekşimsi barbekü sosuyla fırçalanan domuz veya sığır pirzolası.', '', 2),
('840', 'Apple Pie', 'Elmalı Turta', null, null, 'A baked pastry shell filled with spiced sweetened apples, an enduring symbol of American home cooking.', 'Baharatlı ve tatlandırılmış elmalarla doldurulan pişmiş hamur kabuğu, Amerikan ev yemeğinin kalıcı bir simgesi.', '', 3),
('840', 'Clam Chowder', 'İstiridye Çorbası', 'Boston, New England', 'Boston, New England', 'A creamy soup of clams, potatoes, and onion, associated with New England''s coast.', 'New England kıyısıyla özdeşleşen, istiridye, patates ve soğandan yapılan kremamsı bir çorba.', '', 4),
('840', 'Buffalo Wings', 'Buffalo Kanat', 'Buffalo, New York', 'Buffalo, New York', 'Deep-fried chicken wings tossed in a spicy vinegar-based hot sauce, served with blue cheese dip.', 'Acı sirke bazlı bir sosla karıştırılan, mavi peynir sosuyla servis edilen kızarmış tavuk kanatları.', '', 5),
('840', 'Gumbo', 'Gumbo', 'New Orleans', 'New Orleans', 'A thick stew of the Louisiana Creole tradition made with a dark roux, okra, and shellfish or sausage.', 'Koyu bir un-yağ karışımı, bamya ve deniz ürünleri veya sosisle yapılan Louisiana Creole yahnisi.', '', 6),
('840', 'Cheesesteak', 'Peynirli Biftek Sandviçi', 'Philadelphia', 'Philadelphia', 'Thinly sliced grilled beef and melted cheese piled into a long roll.', 'İnce dilimlenmiş ızgara sığır eti ve eritilmiş peynirin uzun bir ekmeğe doldurulmasıyla yapılır.', '', 7),
('840', 'Deep Dish Pizza', 'Derin Tabak Pizza', 'Chicago', 'Chicago', 'A thick-crusted pizza baked in a deep pan with layers of cheese, toppings, and chunky tomato sauce on top.', 'Peynir katmanları, malzemeler ve üzerinde kalın domates sosuyla derin bir tavada pişirilen kalın hamurlu pizza.', '', 8),
('840', 'Chili con Carne', 'Chili con Carne', 'Texas', 'Teksas', 'A spicy stew of chile peppers, meat, and often beans, closely tied to Texan cuisine.', 'Acı biber, et ve genellikle fasulyeyle yapılan, Teksas mutfağıyla yakından ilişkili baharatlı yahni.', '', 9),
('840', 'Key Lime Pie', 'Key Limon Turtası', 'Key West, Florida', 'Key West, Florida', 'A tart custard pie made from key lime juice, sweetened condensed milk, and egg yolks.', 'Key limonu suyu, tatlandırılmış yoğunlaştırılmış süt ve yumurta sarısından yapılan ekşi bir muhallebili turta.', '', 10),
('840', 'Cornbread', 'Mısır Ekmeği', null, null, 'A crumbly bread made from cornmeal, a staple of Southern American cooking.', 'Mısır ununden yapılan, Güney Amerikan mutfağının temel taşlarından ufalanan bir ekmek.', '', 11),
('840', 'Fried Chicken', 'Kızarmış Tavuk', null, null, 'Chicken pieces coated in seasoned flour or batter and deep-fried until crisp.', 'Baharatlı un veya hamura bulanıp çıtır olana kadar kızartılan tavuk parçaları.', '', 12),
('654', 'Saint Helenian Fishcakes', 'Saint Helena Balık Köftesi', null, null, 'Fried patties of mashed potato and local tuna or fish, seasoned with chili, widely considered Saint Helena''s national dish.', 'Adanın ulusal yemeği sayılan, acı biberle tatlandırılmış, ezilmiş patates ve yerel ton balığı veya balıktan yapılan kızarmış köfteler.', '', 1),
('654', 'Plo', 'Plo', null, null, 'A one-pot rice dish cooked with meat or fish and vegetables, showing Cape Malay influence.', 'Cape Malay etkisini yansıtan, et veya balık ve sebzelerle tek tencerede pişirilen bir pirinç yemeği.', '', 2),
('612', 'Pilhi', 'Pilhi', null, null, 'A baked pudding made from grated banana or pumpkin mixed with sugar and coconut, a traditional Pitcairn dish.', 'Rendelenmiş muz veya balkabağının şeker ve hindistancevizi ile karıştırılıp pişirilmesiyle yapılan, geleneksel bir Pitcairn tatlısı.', '', 1),
('660', 'Johnnycake', 'Johnnycake', null, null, 'A fried or baked cornmeal flatbread served alongside most meals.', 'Çoğu yemeğin yanında servis edilen, kızartılmış veya fırınlanmış mısır unu ekmeği.', '', 1),
('660', 'Rice and Peas', 'Pirinç ve Bezelye', null, null, 'Rice cooked with pigeon peas or beans, coconut milk, and seasonings.', 'Güvercin bezelyesi veya fasulye, hindistancevizi sütü ve baharatlarla pişirilen pirinç.', '', 2),
('660', 'Saltfish', 'Tuzlu Balık', null, null, 'Salt-cured fish, often cod, stewed with onions, peppers, and tomatoes.', 'Genellikle morina balığından yapılan, soğan, biber ve domatesle pişirilen tuzlanmış balık.', '', 3),
('238', 'Falklands Roast Lamb', 'Falkland Kızarmış Kuzu', null, null, 'Slow-roasted lamb from the islands'' free-range sheep flocks, a mainstay of Falklands cooking.', 'Adaların serbest gezen koyunlarından elde edilen, yavaşça kızartılan kuzu eti, Falkland mutfağının temel taşıdır.', '', 1),
('238', 'Smoked Mutton', 'Füme Koyun Eti', null, null, 'Mutton cured and smoked, traditionally preserved for the islands'' long winters.', 'Adaların uzun kışları için geleneksel olarak muhafaza edilen, tuzlanıp füme edilmiş koyun eti.', '', 2),
('136', 'Cayman-Style Turtle Stew', 'Cayman Usulü Kaplumbağa Yahnisi', null, null, 'A slow-cooked stew of turtle meat with tomatoes, herbs, and spices, a historic island specialty.', 'Domates, otlar ve baharatlarla yavaşça pişirilen kaplumbağa eti yahnisi, adanın tarihi bir özelliğidir.', '', 1),
('136', 'Fish Rundown', 'Fish Run Down', null, null, 'Fish simmered in a coconut milk broth with breadfruit or vegetables until the sauce reduces down.', 'Balığın, sos koyulaşana kadar ekmek meyvesi veya sebzelerle hindistancevizi sütü suyunda pişirilmesiyle yapılır.', '', 2),
('136', 'Conch Fritters', 'Deniz Salyangozu Kroketi', null, null, 'Deep-fried patties of chopped conch meat blended with peppers and seasoned batter.', 'Doğranmış deniz salyangozu eti, biber ve baharatlı hamurun karıştırılıp kızartılmasıyla yapılan köfteler.', '', 3),
('060', 'Bermuda Fish Chowder', 'Bermuda Balık Çorbası', null, null, 'A rich tomato-based fish soup traditionally spiked with dark rum and sherry peppers.', 'Geleneksel olarak koyu rom ve şeri biberiyle tatlandırılan, zengin domates bazlı bir balık çorbası.', '', 1),
('060', 'Codfish and Potatoes', 'Morina Balığı ve Patates', null, null, 'Salted codfish boiled with potatoes, egg, and banana, a traditional Sunday breakfast.', 'Patates, yumurta ve muzla haşlanan tuzlu morina balığı, geleneksel bir Pazar kahvaltısı.', '', 2),
('060', 'Cassava Pie', 'Manyok Turtası', null, null, 'A savory pie of grated cassava layered with chicken or pork and egg, traditionally served at Christmas.', 'Geleneksel olarak Noel''de servis edilen, rendelenmiş manyokun tavuk veya domuz eti ve yumurtayla katmanlanmasıyla yapılan tuzlu bir turta.', '', 3),
('092', 'Fish and Fungi', 'Balık ve Fungi', null, null, 'Steamed or stewed fish served with fungi, a cornmeal and okra side dish, the territory''s signature meal.', 'Bölgenin amblem yemeği olan, buharda pişmiş veya yahni yapılmış balığın mısır unu ve bamyadan yapılan fungi ile servis edilmesi.', '', 1),
('092', 'Callaloo', 'Callaloo', null, null, 'A leafy green stew made with dasheen or taro leaves, okra, and often crab or salted meat.', 'Dasheen veya taro yaprakları, bamya ve genellikle yengeç veya tuzlanmış etle yapılan yeşillikli bir yahni.', '', 2),
('796', 'Conch Salad', 'Deniz Salyangozu Salatası', null, null, 'Raw diced conch marinated in citrus juice with peppers, onion, and tomato.', 'Biber, soğan ve domatesle, narenciye suyunda marine edilen çiğ doğranmış deniz salyangozu.', '', 1),
('796', 'Conch Fritters', 'Deniz Salyangozu Kroketi', null, null, 'Deep-fried patties of chopped conch meat mixed with peppers and seasoned batter.', 'Doğranmış deniz salyangozu eti, biber ve baharatlı hamurun karıştırılıp kızartılmasıyla yapılan köfteler.', '', 2),
('796', 'Boiled Fish and Grits', 'Haşlanmış Balık ve Mısır Lapası', null, null, 'A traditional breakfast of fish stewed with onions and peppers served over cornmeal grits.', 'Mısır lapası üzerine, soğan ve biberle pişirilmiş balığın servis edildiği geleneksel bir kahvaltı.', '', 3),
('500', 'Goat Water', 'Goat Water', null, null, 'A thick, spiced goat meat stew considered Montserrat''s national dish, often served at festivals.', 'Montserrat''ın ulusal yemeği sayılan, genellikle festivallerde servis edilen koyu, baharatlı keçi eti yahnisi.', '', 1),
('500', 'Mountain Chicken', 'Dağ Tavuğu', null, null, 'A large native frog whose legs were traditionally prepared like chicken, a historic island delicacy.', 'Bacakları geleneksel olarak tavuk gibi hazırlanan, adanın tarihi bir lezzeti olan büyük yerli bir kurbağa türü.', '', 2),
('500', 'Johnnycake', 'Johnnycake', null, null, 'A fried or baked cornmeal flatbread served alongside most meals.', 'Çoğu yemeğin yanında servis edilen, kızartılmış veya fırınlanmış mısır unu ekmeği.', '', 3),
('832', 'Jersey Bean Crock', 'Jersey Fasulye Güveci', null, null, 'A slow-cooked stew of haricot beans, pork, and herbs, a traditional Jersey comfort dish.', 'Fasulye, domuz eti ve otlarla yavaşça pişirilen, geleneksel bir Jersey ev yemeği.', '', 1),
('832', 'Jersey Royal Potatoes', 'Jersey Royal Patatesleri', null, null, 'Small, waxy new potatoes grown only on Jersey, prized for their sweet, earthy flavor and usually served simply buttered.', 'Yalnızca Jersey''de yetiştirilen, tatlı ve toprağımsı lezzetiyle bilinen ve genellikle sade tereyağıyla servis edilen küçük, mumsu yeni patatesler.', '', 2),
('832', 'Jersey Wonders', 'Jersey Wonders', null, null, 'Twisted knots of sweet dough deep-fried until golden, traditionally made at low tide.', 'Altın rengi olana kadar kızartılan, geleneksel olarak deniz çekilirken yapılan bükülmüş tatlı hamur düğümleri.', '', 3),
('831', 'Guernsey Bean Jar', 'Guernsey Fasulye Kavanozu', null, null, 'A slow-baked casserole of haricot beans, pork, and herbs cooked for hours in a covered jar.', 'Kapaklı bir kavanozda saatlerce pişirilen fasulye, domuz eti ve otlardan yapılan yavaş fırınlanmış güveç.', '', 1),
('831', 'Guernsey Gâche', 'Guernsey Gâche', null, null, 'A dense fruit loaf studded with raisins and mixed peel, traditionally sliced and buttered.', 'Kuru üzüm ve karışık kabukla dolu, geleneksel olarak dilimlenip tereyağlanan yoğun bir meyveli ekmek.', '', 2),
('833', 'Manx Kippers', 'Manx Kippers', 'Peel', 'Peel', 'Herring split, salted, and cold-smoked over oak chips, a specialty of the town of Peel.', 'Peel kasabasının bir özelliği olan, yarılıp tuzlanan ve meşe talaşı üzerinde soğuk dumanlanan ringa balığı.', '', 1),
('833', 'Queenies', 'Queenies', null, null, 'Small local scallops, typically pan-fried in butter and garlic.', 'Genellikle tereyağı ve sarımsakla tavada pişirilen küçük yerel deniz tarakları.', '', 2),
('833', 'Chips, Cheese and Gravy', 'Patates Kızartması, Peynir ve Sos', null, null, 'A hearty modern Manx favorite of fries topped with melted cheese and gravy.', 'Eritilmiş peynir ve sosla kaplanmış patates kızartmasından oluşan, modern bir Manx favorisi.', '', 3),
('826', 'Fish and Chips', 'Balık ve Patates Kızartması', null, null, 'Battered fried fish served with thick-cut fried potatoes, a national favorite.', 'Kalın kesilmiş kızarmış patatesle servis edilen, hamura bulanmış kızarmış balık, ulusal bir favori.', '', 1),
('826', 'Sunday Roast', 'Pazar Kızartması', null, null, 'Roasted meat served with roast potatoes, vegetables, gravy, and Yorkshire pudding, traditionally eaten on Sundays.', 'Kızarmış patates, sebzeler, sos ve Yorkshire puddingiyle servis edilen, geleneksel olarak pazar günleri yenen kızarmış et.', '', 2),
('826', 'Shepherd''s Pie', 'Çoban Böreği', null, null, 'A baked dish of minced lamb in gravy topped with a layer of mashed potato.', 'Üzeri püre patatesle kaplanan, soslu kıyma kuzu etinden yapılan fırınlanmış bir yemek.', '', 3),
('826', 'Full English Breakfast', 'Tam İngiliz Kahvaltısı', null, null, 'A hearty plate of eggs, bacon, sausages, beans, tomatoes, and toast.', 'Yumurta, pastırma, sosis, fasulye, domates ve kızarmış ekmekten oluşan doyurucu bir tabak.', '', 4),
('826', 'Bangers and Mash', 'Sosis ve Patates Püresi', null, null, 'Grilled sausages served over mashed potato with onion gravy.', 'Soğanlı sosla, patates püresi üzerinde servis edilen ızgara sosisler.', '', 5),
('826', 'Haggis', 'Haggis', 'Scotland', 'İskoçya', 'A savory pudding of minced sheep''s offal, oats, and spices traditionally cooked in a sheep''s stomach casing.', 'Geleneksel olarak bir koyun midesi zarında pişirilen, kıyılmış koyun sakatatı, yulaf ve baharatlardan yapılan tuzlu bir puding.', '', 6),
