('826', 'Steak and Kidney Pie', 'Biftek ve Böbrek Turtası', null, null, 'A pastry pie filled with braised beef and kidney in a rich gravy.', 'Zengin bir sosta pişirilmiş sığır eti ve böbrekle doldurulan hamur turtası.', '', 8),
('826', 'Yorkshire Pudding', 'Yorkshire Puddingi', 'Yorkshire', 'Yorkshire', 'A baked batter of eggs, flour, and milk that puffs up crisp, traditionally served with roast beef.', 'Geleneksel olarak rosto sığır etiyle servis edilen, pişince çıtır şekilde kabaran yumurta, un ve sütten yapılan hamur.', '', 9),
('826', 'Beef Wellington', 'Beef Wellington', null, null, 'Beef fillet coated in pâté and mushroom duxelles, wrapped in puff pastry and baked.', 'Ciğer ezmesi ve mantar karışımıyla kaplanan, milföy hamuruna sarılıp fırınlanan sığır filetosu.', '', 10),
('826', 'Trifle', 'Trifle', null, null, 'A layered dessert of sponge cake, fruit, custard, jelly, and whipped cream.', 'Pandispanya, meyve, muhallebi, jöle ve kremadan oluşan katmanlı bir tatlı.', '', 11),
('826', 'Chicken Tikka Masala', 'Tavuk Tikka Masala', null, null, 'Grilled marinated chicken chunks served in a creamy spiced tomato sauce, widely regarded as a modern British classic.', 'Kremamsı baharatlı domates sosunda servis edilen, marine edilip ızgara yapılan tavuk parçaları, modern bir İngiliz klasiği sayılır.', '', 12),
('784', 'Machbous', 'Machbous', null, null, 'Spiced rice cooked with meat or fish and dried lime, the emblematic Emirati dish.', 'Et veya balık ve kurutulmuş limonla pişirilen baharatlı pirinç, Emirlik''in amblem yemeği.', '', 1),
