('784', 'Luqaimat', 'Luqaimat', null, null, 'Deep-fried sweet dumplings drizzled with date syrup or honey.', 'Üzerine hurma pekmezi veya bal gezdirilen, kızarmış tatlı hamur toplarıdır.', '', 3),
('784', 'Balaleet', 'Balaleet', null, null, 'Sweet saffron-spiced vermicelli noodles topped with a savory folded omelet.', 'Üzerine tuzlu bir omlet konulan, safranlı tatlı şehriye.', '', 4),
('784', 'Khameer Bread', 'Khameer Ekmeği', null, null, 'A soft, slightly sweet leavened flatbread traditionally baked and served with cheese or honey at breakfast.', 'Geleneksel olarak kahvaltıda peynir veya balla servis edilen, yumuşak ve hafif tatlı mayalı yassı ekmek.', '', 5),
('804', 'Borscht', 'Borş', null, null, 'A vibrant beet soup often made with cabbage and meat, served with a dollop of sour cream.', 'Genellikle lahana ve etle yapılan, üzerine bir kaşık ekşi krema konulan canlı renkli pancar çorbası.', '', 1),
('804', 'Varenyky', 'Varenyky', null, null, 'Boiled dumplings filled with potato, cheese, cabbage, or fruit.', 'Patates, peynir, lahana veya meyveyle doldurulan haşlanmış mantı.', '', 2),
('804', 'Holubtsi', 'Holubtsi', null, null, 'Cabbage leaves rolled around a filling of meat and rice, then simmered in tomato sauce.', 'Et ve pirinç harcının lahana yapraklarına sarılıp domates sosunda pişirilmesiyle yapılır.', '', 3),
('804', 'Deruny', 'Deruny', null, null, 'Fried potato pancakes, often served with sour cream.', 'Genellikle ekşi kremayla servis edilen kızarmış patates krepleri.', '', 4),
('804', 'Salo', 'Salo', null, null, 'Cured slabs of pork fat, salted or smoked, traditionally eaten thinly sliced on bread.', 'Geleneksel olarak ince dilimlenip ekmek üzerinde yenen, tuzlanmış veya füme edilmiş domuz yağı dilimleri.', '', 5),
('804', 'Chicken Kyiv', 'Kiev Tavuğu', 'Kyiv', 'Kiev', 'A chicken breast fillet pounded, filled with cold herb butter, then breaded and fried until the butter stays molten inside.', 'Dövülüp inceltilen tavuk göğsü filetosunun, soğuk otlu tereyağıyla doldurulup galeta ununa bulanarak, içindeki tereyağı erimiş halde kalacak şekilde kızartılmasıyla yapılır.', '', 6),
('804', 'Syrniki', 'Sirniki', null, null, 'Fried farmer''s cheese pancakes, often served with sour cream, honey, or jam.', 'Genellikle ekşi krema, bal veya reçelle servis edilen kızarmış lor peyniri krepleri.', '', 7),
('800', 'Matoke', 'Matoke', null, null, 'Green bananas steamed and mashed, forming the everyday staple of Ugandan meals.', 'Buharda pişirilip ezilen yeşil muzlardan yapılan, Uganda yemeklerinin günlük temel besini.', '', 1),
('800', 'Luwombo', 'Luwombo', null, null, 'Meat or groundnut stew steamed slowly inside a wrapped banana leaf parcel.', 'Etin veya yer fıstığı yahnisinin, muz yaprağına sarılıp yavaşça buharda pişirilmesiyle yapılır.', '', 2),
('800', 'Rolex', 'Rolex', 'Kampala', 'Kampala', 'A rolled chapati wrapped around a fried omelet with vegetables, a popular Kampala street food.', 'Sebzeli sahanda yumurtanın bir çapati içine sarılmasıyla yapılan, Kampala''da popüler bir sokak yemeği.', '', 3),
('800', 'Posho', 'Posho', null, null, 'A stiff maize-meal porridge similar to ugali, eaten with sauces or stews.', 'Ugaliye benzeyen, sos veya yahnilerle yenen sert bir mısır unu lapası.', '', 4),
('800', 'Binyebwa (Groundnut Sauce)', 'Binyebwa (Yer Fıstığı Sosu)', null, null, 'A creamy sauce of ground peanuts simmered with vegetables or meat, served over matoke or rice.', 'Sebze veya etle pişirilen, matoke ya da pirinç üzerinde servis edilen kremamsı çekilmiş yer fıstığı sosu.', '', 5),
('795', 'Plov', 'Palov', null, null, 'A rice pilaf cooked with lamb or beef, carrots, and onions in one pot.', 'Kuzu veya sığır eti, havuç ve soğanla tek kapta pişirilen bir pirinç pilavı.', '', 1),
('795', 'Manty', 'Mantı', null, null, 'Steamed dumplings filled with spiced minced meat and onion.', 'Baharatlı kıyma ve soğanla doldurulan buharda pişirilmiş mantı.', '', 2),
('795', 'Ishlekli', 'İşlekli', null, null, 'A pan-fried flatbread stuffed with meat, onion, and sometimes pumpkin.', 'Et, soğan ve bazen kabakla doldurularak tavada kızartılan bir hamur işi.', '', 3),
