('792', 'Doner Kebab', 'Döner Kebap', null, null, 'Seasoned meat stacked and roasted on a vertical rotisserie, then thinly sliced.', 'Baharatlanmış etin dikey bir şişte kızartılıp ince ince dilimlenmesiyle yapılır.', '', 2),
('792', 'Baklava', 'Baklava', null, null, 'Layers of thin filo pastry filled with chopped nuts and soaked in sweet syrup.', 'İnce yufka katları arasına dövülmüş fındık/ceviz konularak şerbete batırılan bir tatlı.', '', 3),
('792', 'Turkish Dumplings (Mantı)', 'Mantı', null, null, 'Tiny boiled dumplings filled with seasoned ground meat, topped with yogurt and garlic.', 'Baharatlı kıymayla doldurulan minik haşlanmış mantılar, üzerine sarımsaklı yoğurt ve tereyağı ile servis edilir.', '', 4),
('792', 'Lahmacun', 'Lahmacun', null, null, 'A thin, crispy flatbread topped with minced meat, vegetables, and herbs, baked in a hot oven.', 'İnce ve gevrek bir hamurun üzerine kıyma, sebze ve otlar konularak sıcak fırında pişirilir.', '', 5),
('792', 'Turkish Pide', 'Pide', null, null, 'A boat-shaped flatbread topped with cheese, meat, or eggs and baked in a stone oven.', 'Peynir, kıyma veya yumurta konulan kayık şeklindeki hamurun taş fırında pişirilmesiyle yapılır.', '', 6),
('792', 'Iskender Kebab', 'İskender Kebap', 'Bursa', 'Bursa', 'Sliced doner meat served over pide bread with tomato sauce, melted butter, and yogurt.', 'Dilimlenmiş döner etinin pide üzerine, domates sosu, eritilmiş tereyağı ve yoğurtla servis edilmesidir.', '', 7),
('792', 'Menemen', 'Menemen', null, null, 'Eggs scrambled with tomatoes, green peppers, and onions in olive oil.', 'Domates, yeşil biber ve soğanın zeytinyağında yumurtayla karıştırılarak pişirilmesidir.', '', 8),
('792', 'Dolma (Stuffed Grape Leaves)', 'Yaprak Sarma', null, null, 'Grape leaves rolled around a filling of rice, herbs, and sometimes minced meat.', 'Asma yapraklarının pirinç, otlar ve bazen kıyma ile doldurularak sarılmasıdır.', '', 9),
('792', 'Turkish Meatballs (Köfte)', 'Köfte', null, null, 'Seasoned ground meat shaped into patties and grilled or pan-fried.', 'Baharatlı kıymanın köfte şeklinde yoğrularak ızgara veya tavada pişirilmesidir.', '', 10),
('792', 'Cig Kofte', 'Çiğ Köfte', 'Şanlıurfa', 'Şanlıurfa', 'A spiced paste of fine bulgur, tomato paste, and walnuts, kneaded until smooth and served wrapped in lettuce.', 'İnce bulgur, salça ve cevizin baharatlarla yoğrularak marul yaprağına sarılıp servis edildiği bir mezedir.', '', 11),
('792', 'Kunefe', 'Künefe', 'Hatay', 'Hatay', 'Shredded pastry layered with soft cheese, baked, and soaked in sweet syrup.', 'Tel kadayıfın arasına lor peyniri konularak fırınlanması ve şerbetle buluşturulmasıdır.', '', 12),
('788', 'Couscous', 'Kuskus', null, null, 'Steamed semolina grains served with a stew of vegetables, meat, or fish.', 'Buharda pişirilen irmik tanelerinin sebze, et veya balık yahnisiyle servis edilmesidir.', '', 1),
('788', 'Brik', 'Brik', null, null, 'A thin pastry sheet folded around an egg, tuna, and parsley filling and deep-fried.', 'İnce bir hamur yaprağının yumurta, ton balığı ve maydanozla doldurulup kızartılmasıdır.', '', 2),
('788', 'Lablabi', 'Lablabi', null, null, 'A hearty chickpea soup flavored with garlic, cumin, and harissa, poured over stale bread.', 'Sarımsak, kimyon ve harisa ile tatlandırılan nohut çorbasının bayat ekmek üzerine dökülmesiyle yapılır.', '', 3),
('788', 'Ojja', 'Ojja', null, null, 'A spicy tomato and pepper stew with eggs poached on top, often with merguez sausage.', 'Domates ve biberli acı bir yahninin üzerine yumurta kırılarak, genellikle merguez sosisiyle pişirilmesidir.', '', 4),
('788', 'Tunisian Tajine', 'Tunus Usulü Tajin', null, null, 'A dense baked dish of eggs, cheese, and meat or vegetables, closer to a frittata than a Moroccan tagine.', 'Yumurta, peynir ve et ya da sebzeyle yapılan, Fas tajininden çok bir kaşarlı omlete benzeyen fırın yemeğidir.', '', 5),
('788', 'Merguez', 'Merguez', null, null, 'A spicy, deep-red lamb or beef sausage flavored with harissa and cumin.', 'Harisa ve kimyonla tatlandırılan, koyu kırmızı renkli acı bir kuzu veya sığır sosisidir.', '', 6),
('780', 'Doubles', 'Doubles', null, null, 'Two pieces of fried flatbread sandwiching curried chickpeas, topped with chutneys.', 'İki parça kızarmış hamurun arasına köri soslu nohut konularak çeşitli soslarla servis edilmesidir.', '', 1),
('780', 'Bake and Shark', 'Bake and Shark', 'Maracas Bay', 'Maracas Körfezi', 'Fried shark fillet served in a fried bread bun with a choice of sauces and toppings.', 'Kızarmış köpekbalığı filetosunun kızarmış bir ekmeğin içine çeşitli soslarla konularak servis edilmesidir.', '', 2),
('780', 'Roti (Buss Up Shut)', 'Roti', null, null, 'A shredded, flaky flatbread served alongside curried meat, chicken, or vegetables.', 'Parçalanmış, katmanlı bir hamur ekmeğinin köri soslu et, tavuk veya sebzeyle servis edilmesidir.', '', 3),
('780', 'Callaloo', 'Callaloo', null, null, 'A thick stew of dasheen or taro leaves cooked with okra, coconut milk, and crab or meat.', 'Taro yapraklarının bamya, hindistan cevizi sütü ve yengeç veya etle pişirildiği koyu kıvamlı bir yemektir.', '', 4),
('780', 'Pelau', 'Pelau', null, null, 'Rice and pigeon peas cooked with caramelized meat, coconut milk, and vegetables in one pot.', 'Pirinç ve güvercin bezelyesinin karamelize et, hindistan cevizi sütü ve sebzelerle tek kapta pişirilmesidir.', '', 5),
('776', 'Lu Pulu', 'Lu Pulu', null, null, 'Taro leaves parceled around corned beef and coconut cream, traditionally cooked in an underground oven.', 'Taro yapraklarının konserve sığır eti ve hindistan cevizi kremasıyla sarılıp geleneksel olarak yer altı fırınında pişirilmesidir.', '', 1),
('776', 'Ota Ika', 'Ota Ika', null, null, 'Raw fish marinated in coconut milk, lime juice, and chopped vegetables.', 'Çiğ balığın hindistan cevizi sütü, limon suyu ve doğranmış sebzelerle marine edilmesidir.', '', 2),
('776', 'Faikakai', 'Faikakai', null, null, 'Boiled dumplings served in a warm caramelized coconut syrup.', 'Haşlanmış hamur toplarının sıcak karamelize hindistan cevizi şurubuyla servis edilmesidir.', '', 3),
('768', 'Pâte', 'Pate', null, null, 'A thick, smooth dough made from fermented corn or cassava flour, eaten with sauce.', 'Fermente mısır veya manyok unundan yapılan koyu ve pürüzsüz bir hamurun sosla yenmesidir.', '', 1),
('768', 'Fufu', 'Fufu', null, null, 'Pounded cassava or yam formed into a smooth dough and eaten with soup or stew.', 'Manyok veya yam kökünün dövülerek pürüzsüz bir hamur haline getirilip çorba veya yahniyle yenmesidir.', '', 2),
('768', 'Riz Sauce Arachide', 'Fıstık Soslu Pilav', null, null, 'Rice served with a rich, savory peanut sauce, often with meat or fish.', 'Pirincin zengin ve tuzlu bir yer fıstığı sosuyla, genellikle et veya balıkla servis edilmesidir.', '', 3),
('768', 'Akpan', 'Akpan', null, null, 'A fermented corn pudding often mixed with yogurt and sugar, popular as street food.', 'Genellikle yoğurt ve şekerle karıştırılan fermente mısır pudinginin sokak yiyeceği olarak tüketilmesidir.', '', 4),
('626', 'Batar Da''an', 'Batar Da''an', null, null, 'A stew of corn, mung beans, and pumpkin simmered together, widely considered Timor-Leste''s national dish.', 'Mısır, maş fasulyesi ve balkabağının birlikte pişirildiği, Timor-Leste''nin milli yemeği sayılan bir güveçtir.', '', 1),
('626', 'Ikan Sabuko', 'Ikan Sabuko (Izgara Balık)', null, null, 'Grilled mackerel or skipjack tuna, a staple of the coastal diet.', 'Sahil kesiminin temel besinlerinden olan ızgara uskumru veya orkinos balığıdır.', '', 2),
('626', 'Ai-Manas', 'Ai-Manas (Acı Sos)', null, null, 'A fiery chili paste made from local chilies, lime, and salt, served alongside most meals.', 'Yerel biberler, limon ve tuzla yapılan, çoğu yemeğin yanında servis edilen acı bir soğuk sostur.', '', 3),
('764', 'Pad Thai', 'Pad Thai', null, null, 'Stir-fried rice noodles with egg, tofu or shrimp, bean sprouts, and tamarind sauce.', 'Pirinç eriştesinin yumurta, tofu veya karides, filiz ve demirhindi sosuyla wokta kızartılmasıdır.', '', 1),
('764', 'Tom Yum Goong', 'Tom Yum Goong', null, null, 'A hot and sour shrimp soup flavored with lemongrass, galangal, and lime.', 'Limon otu, galanga ve limonla tatlandırılan acı ve ekşi bir karides çorbasıdır.', '', 2),
('764', 'Green Curry', 'Yeşil Köri', null, null, 'A creamy curry made with green chilies, coconut milk, meat, and Thai eggplant.', 'Yeşil biber, hindistan cevizi sütü, et ve Tay patlıcanıyla yapılan kremamsı bir köridir.', '', 3),
('764', 'Som Tam', 'Som Tam (Yeşil Papaya Salatası)', null, null, 'A spicy salad of shredded green papaya, chilies, lime, and fish sauce.', 'Rendelenmiş yeşil papaya, biber, limon ve balık sosuyla yapılan acı bir salatadır.', '', 4),
('764', 'Massaman Curry', 'Massaman Köri', null, null, 'A mild, rich curry blending coconut milk with potatoes, peanuts, and warm spices.', 'Hindistan cevizi sütü, patates, fıstık ve sıcak baharatların birleştiği hafif ve zengin bir köridir.', '', 5),
('764', 'Tom Kha Gai', 'Tom Kha Gai', null, null, 'A creamy chicken soup made with coconut milk, galangal, and lemongrass.', 'Hindistan cevizi sütü, galanga ve limon otuyla yapılan kremamsı bir tavuk çorbasıdır.', '', 6),
('764', 'Pad Kra Pao', 'Pad Kra Pao', null, null, 'Minced meat stir-fried with holy basil and chilies, usually served over rice with a fried egg.', 'Kıyılmış etin kutsal fesleğen ve biberle kızartılıp genellikle pirinç ve sahanda yumurtayla servis edilmesidir.', '', 7),
('764', 'Larb', 'Larb', null, null, 'A minced meat salad tossed with lime juice, toasted rice powder, chilies, and herbs.', 'Kıyılmış etin limon suyu, kavrulmuş pirinç tozu, biber ve otlarla karıştırıldığı bir salatadır.', '', 8),
('764', 'Khao Soi', 'Khao Soi', 'Chiang Mai', 'Chiang Mai', 'Egg noodles in a curried coconut broth, topped with crispy fried noodles.', 'Yumurtalı eriştenin köri soslu hindistan cevizi çorbasında, üzerine gevrek kızarmış erişte eklenerek servis edilmesidir.', '', 9),
('764', 'Mango Sticky Rice', 'Mangolu Yapışkan Pirinç', null, null, 'Sweet glutinous rice served with fresh mango slices and coconut cream.', 'Tatlı yapışkan pirincin taze mango dilimleri ve hindistan cevizi kremasıyla servis edilmesidir.', '', 10),
('764', 'Satay', 'Saten (Satay)', null, null, 'Grilled skewers of marinated meat served with a peanut dipping sauce.', 'Marine edilmiş etin şişe dizilerek ızgara yapılması ve yer fıstığı sosuyla servis edilmesidir.', '', 11),
('764', 'Khao Pad', 'Khao Pad (Kızarmış Pirinç)', null, null, 'Thai-style fried rice with egg, vegetables, and a choice of meat or seafood.', 'Tay usulü kızarmış pirincin yumurta, sebze ve et ya da deniz ürünüyle hazırlanmasıdır.', '', 12),
('834', 'Ugali', 'Ugali', null, null, 'A stiff porridge made from maize flour, the staple starch eaten alongside stews.', 'Mısır ununun sertçe pişirilmesiyle yapılan, yahnilerin yanında yenen temel nişastalı yemektir.', '', 1),
('834', 'Nyama Choma', 'Nyama Choma (Izgara Et)', null, null, 'Grilled goat or beef, simply seasoned and cooked slowly over charcoal.', 'Basitçe baharatlanan keçi veya sığır etinin kömür ateşinde yavaşça ızgara edilmesidir.', '', 2),
('834', 'Pilau', 'Pilau', null, null, 'Spiced rice cooked with meat and aromatic spices, reflecting Swahili coastal influence.', 'Baharatlı pirincin et ve aromatik baharatlarla pişirildiği, Swahili sahil mutfağından etkilenen bir yemektir.', '', 3),
('834', 'Mishkaki', 'Mishkaki', null, null, 'Marinated meat skewers grilled over an open flame, a popular street food.', 'Marine edilmiş etin şişe dizilerek açık ateşte közlenmesiyle yapılan popüler bir sokak yemeğidir.', '', 4),
('834', 'Zanzibar Mix', 'Zanzibar Mix', 'Zanzibar', 'Zanzibar', 'A street-food soup of cassava, potato, and fried bhajia in a savory broth topped with chutney.', 'Manyok, patates ve kızarmış bhajianın tuzlu bir çorbada birleştirilip üzerine sos eklenen bir sokak yemeğidir.', '', 5),
('834', 'Chapati', 'Chapati', null, null, 'A soft, pan-fried flatbread of Indian origin, commonly served as a side dish.', 'Hindistan kökenli, tavada pişirilen yumuşak bir yassı ekmek olup genellikle yan yemek olarak servis edilir.', '', 6),
('762', 'Osh (Plov)', 'Oş (Palov)', null, null, 'A rice pilaf cooked with meat, carrots, and onions, considered Tajikistan''s national dish.', 'Et, havuç ve soğanla pişirilen, Tacikistan''ın milli yemeği sayılan bir pirinç pilavıdır.', '', 1),
('762', 'Qurutob', 'Kurutob', null, null, 'Crumbled flatbread soaked in a yogurt-based sauce and topped with fried onions and vegetables.', 'Parçalanmış hamur ekmeğinin yoğurt bazlı bir sosa batırılıp kızarmış soğan ve sebzeyle süslenmesidir.', '', 2),
('762', 'Laghman', 'Laghman', null, null, 'Hand-pulled noodles served with a stir-fried sauce of meat and vegetables.', 'Elle çekilen eriştenin et ve sebzeli bir sosla wokta pişirilerek servis edilmesidir.', '', 3),
('762', 'Manti', 'Mantı', null, null, 'Steamed dumplings filled with seasoned meat and onion.', 'Baharatlı et ve soğanla doldurulan buharda pişirilmiş mantıdır.', '', 4),
('762', 'Sambusa', 'Samsa', null, null, 'A baked or fried pastry filled with spiced meat or pumpkin.', 'Baharatlı et veya kabakla doldurulan fırınlanmış ya da kızartılmış bir hamur işidir.', '', 5),
('158', 'Beef Noodle Soup', 'Sığır Etli Erişte Çorbası', null, null, 'Wheat noodles in a rich, slow-braised beef broth with tender beef chunks and greens.', 'Buğday eriştesinin, yavaş pişirilmiş zengin bir sığır et suyunda yumuşacık et parçaları ve yeşilliklerle servis edilmesidir.', '', 1),
('158', 'Xiaolongbao', 'Xiaolongbao', null, null, 'Steamed soup dumplings filled with pork and a savory broth that bursts when bitten.', 'Domuz eti ve içinde ısırıldığında akan lezzetli bir et suyuyla doldurulan buharda pişmiş mantılardır.', '', 2),
('158', 'Oyster Omelet', 'İstiridyeli Omlet', null, null, 'Fresh oysters folded into an egg and starch batter, pan-fried until crisp and topped with a sweet sauce.', 'Taze istiridyelerin yumurta ve nişasta hamuruyla karıştırılıp gevrekleşene kadar kızartılması ve tatlı sosla servis edilmesidir.', '', 3),
('158', 'Braised Pork Rice', 'Soslu Kıyma Pilavı (Lu Rou Fan)', null, null, 'Steamed rice topped with soy-braised minced pork belly and its savory sauce.', 'Buharda pişmiş pirincin üzerine soya sosunda pişirilmiş kıyılmış domuz göğsü ve sosunun eklenmesidir.', '', 4),
('158', 'Stinky Tofu', 'Kokulu Tofu', null, null, 'Fermented tofu with a pungent aroma, deep-fried and served with pickled cabbage.', 'Keskin kokulu fermente tofunun derin yağda kızartılıp turşu lahanayla servis edilmesidir.', '', 5),
('158', 'Gua Bao', 'Gua Bao', null, null, 'A steamed, folded bun filled with braised pork belly, pickled greens, and peanut powder.', 'Buharda pişmiş katlanmış bir çöreğin haşlanmış domuz göğsü, turşu yeşillik ve fıstık tozuyla doldurulmasıdır.', '', 6),
('158', 'Bubble Tea', 'İncili Süt Çayı (Bubble Tea)', null, null, 'Sweet milk tea shaken with chewy tapioca pearls, served cold with a wide straw.', 'Tatlı sütlü çayın çiğnenebilir tapyoka inci taneleriyle çalkalanıp soğuk olarak geniş bir pipetle servis edilmesidir.', '', 7),
('158', 'Pineapple Cake', 'Ananaslı Kek', null, null, 'A buttery shortcrust pastry filled with sweet-tart pineapple jam.', 'Tereyağlı bir hamurun içine tatlı-ekşi ananas reçeli doldurularak pişirilmesidir.', '', 8),
('158', 'Danzai Noodles', 'Danzai Noodles', 'Tainan', 'Tainan', 'Thin noodles topped with a savory minced pork sauce, shrimp, and a boiled egg.', 'İnce eriştenin üzerine lezzetli kıyma sosu, karides ve haşlanmış yumurta eklenerek servis edilmesidir.', '', 9),
('760', 'Kibbeh', 'Kibbe', null, null, 'A torpedo-shaped shell of bulgur and minced meat, stuffed with spiced meat and pine nuts, then fried.', 'Bulgur ve kıymadan yapılan mekik şeklindeki bir kabuğun baharatlı et ve çamfıstığıyla doldurulup kızartılmasıdır.', '', 1),
('760', 'Hummus', 'Humus', null, null, 'A creamy dip of mashed chickpeas blended with tahini, lemon juice, and garlic.', 'Ezilmiş nohutun tahin, limon suyu ve sarımsakla karıştırıldığı kremamsı bir mezedir.', '', 2),
('760', 'Fattoush', 'Fettuş', null, null, 'A salad of mixed greens and vegetables tossed with toasted or fried pieces of pita bread.', 'Karışık yeşillik ve sebzelerin kızarmış pide parçalarıyla karıştırıldığı bir salatadır.', '', 3),
('760', 'Shawarma', 'Şavarma', null, null, 'Marinated meat stacked and roasted on a vertical spit, then shaved and wrapped in flatbread.', 'Marine edilmiş etin dikey bir şişte kızartılıp ince dilimlenerek yassı ekmeğe sarılmasıdır.', '', 4),
('760', 'Baba Ghanoush', 'Babagannuş', null, null, 'A smoky dip of roasted eggplant blended with tahini, garlic, and lemon.', 'Kömürde közlenmiş patlıcanın tahin, sarımsak ve limonla karıştırıldığı dumanlı bir mezedir.', '', 5),
('760', 'Muhammara', 'Muhammara', 'Aleppo', 'Halep', 'A spread of roasted red peppers, walnuts, breadcrumbs, and pomegranate molasses.', 'Közlenmiş kırmızı biber, ceviz, galeta unu ve nar ekşisiyle yapılan bir mezedir.', '', 6),
('760', 'Maqluba', 'Maklube', null, null, 'A layered dish of rice, fried vegetables, and meat cooked in a pot, then flipped upside down to serve.', 'Pirinç, kızarmış sebze ve etin bir tencerede katman katman pişirilip ters çevrilerek servis edilmesidir.', '', 7),
('760', 'Yabraq', 'Yaprak Dolması', null, null, 'Grape leaves rolled around a filling of rice, herbs, and often minced meat.', 'Asma yapraklarının pirinç, otlar ve genellikle kıyma ile doldurularak sarılmasıdır.', '', 8),
('756', 'Fondue', 'Peynir Fondüsü', null, null, 'Melted cheese and white wine kept warm in a communal pot, eaten by dipping bread on long forks.', 'Eritilmiş peynir ve beyaz şarabın ortak bir kapta sıcak tutulup uzun çatallarla ekmek batırılarak yenmesidir.', '', 1),
('756', 'Raclette', 'Raclette', null, null, 'Cheese melted and scraped onto boiled potatoes, pickles, and cured meats.', 'Eritilen peynirin haşlanmış patates, turşu ve şarküteri ürünlerinin üzerine kazınarak dökülmesidir.', '', 2),
('756', 'Rösti', 'Rösti', null, null, 'Shredded potatoes formed into a cake and pan-fried until golden and crisp.', 'Rendelenmiş patatesin bir pasta şeklinde biçimlendirilip altın rengi ve gevrek olana kadar tavada kızartılmasıdır.', '', 3),
('756', 'Zurich-Style Sliced Veal', 'Zürih Usulü Dilim Et', 'Zurich', 'Zürih', 'Sliced veal and mushrooms in a creamy white wine sauce, usually served with rösti.', 'Dilimlenmiş dana etinin ve mantarın kremamsı beyaz şarap sosunda pişirilip genellikle rösti ile servis edilmesidir.', '', 4),
('756', 'Älplermagronen', 'Älplermagronen', null, null, 'Macaroni baked with potatoes, cheese, and cream, traditionally topped with stewed apples.', 'Makarnanın patates, peynir ve kremayla fırınlanıp geleneksel olarak elma kompostosuyla servis edilmesidir.', '', 5),
('756', 'Birchermüsli', 'Birchermüsli', null, null, 'Raw oats soaked with milk or yogurt, grated apple, nuts, and fruit, eaten at breakfast.', 'Yulafın süt veya yoğurt, rendelenmiş elma, kuruyemiş ve meyveyle ıslatılarak kahvaltıda yenmesidir.', '', 6),
('752', 'Köttbullar', 'İsveç Köftesi', null, null, 'Small pan-fried meatballs served with cream sauce, boiled potatoes, and lingonberry jam.', 'Küçük tavada kızartılmış köftelerin krema sosu, haşlanmış patates ve yaban mersini reçeliyle servis edilmesidir.', '', 1),
('752', 'Gravlax', 'Gravlaks', null, null, 'Raw salmon cured with salt, sugar, and dill, sliced thinly and served with a mustard-dill sauce.', 'Çiğ somonun tuz, şeker ve dereotuyla tuzlanıp ince dilimlenerek hardallı-dereotlu sosla servis edilmesidir.', '', 2),
('752', 'Smörgåsbord', 'Smörgåsbord', null, null, 'A buffet spread of cold and warm dishes including cured fish, meats, and cheeses.', 'Tuzlanmış balık, et ve peynir çeşitlerini içeren sıcak ve soğuk yemeklerden oluşan bir açık büfedir.', '', 3),
('752', 'Kanelbulle', 'Tarçınlı Çörek', null, null, 'A soft, spiral-shaped sweet roll flavored with cinnamon and cardamom.', 'Tarçın ve kakule ile tatlandırılan yumuşak, sarmal şeklinde tatlı bir çörektir.', '', 4),
('752', 'Surströmming', 'Surströmming', null, null, 'Fermented Baltic herring with an intensely pungent smell, traditionally eaten with flatbread.', 'Şiddetli keskin kokusuyla bilinen fermente Baltık ringasının geleneksel olarak yassı ekmekle yenmesidir.', '', 5),
('752', 'Jansson''s Temptation', 'Jansson''un Ayartması', null, null, 'A creamy baked casserole of potatoes, onions, and pickled sprats.', 'Patates, soğan ve marine edilmiş çaça balığından yapılan kremamsı bir fırın yemeğidir.', '', 6),
('748', 'Sishwala', 'Sishwala', null, null, 'A thick porridge made from ground maize meal, the daily staple food.', 'Öğütülmüş mısır unundan yapılan, günlük temel besin olan koyu bir lapadır.', '', 1),
('748', 'Sidvudvu', 'Sidvudvu', null, null, 'A soft porridge made by cooking pumpkin together with maize meal.', 'Balkabağının mısır unuyla birlikte pişirilmesiyle yapılan yumuşak bir lapadır.', '', 2),
('748', 'Emasi', 'Emasi', null, null, 'Naturally fermented milk with a thin, yogurt-like consistency, often eaten with porridge.', 'Yoğurda benzer akışkan kıvamda, doğal olarak fermente olmuş sütün genellikle lapayla yenmesidir.', '', 3),
('748', 'Incwancwa', 'Incwancwa', null, null, 'A fermented maize porridge with a distinctive sour taste.', 'Kendine özgü ekşi bir tada sahip fermente edilmiş mısır lapasıdır.', '', 4),
('740', 'Pom', 'Pom', null, null, 'A baked casserole of grated pomtajer root mixed with chicken and citrus, a festive dish of Surinamese-Jewish origin.', 'Rendelenmiş pomtajer kökünün tavuk ve narenciyeyle karıştırılıp fırınlandığı, Surinam-Yahudi kökenli bayramlık bir yemektir.', '', 1),
('740', 'Roti', 'Roti', null, null, 'A flatbread served alongside curried chicken or vegetables, reflecting Suriname''s Indian heritage.', 'Köri soslu tavuk veya sebzeyle servis edilen, Surinam''ın Hint mirasını yansıtan bir yassı ekmektir.', '', 2),
('740', 'Moksi Alesi', 'Moksi Alesi', null, null, 'A mixed rice dish cooked with meat, vegetables, and often salted fish.', 'Pirincin et, sebze ve genellikle tuzlu balıkla birlikte pişirilmesiyle yapılan karışık bir pirinç yemeğidir.', '', 3),
('740', 'Bakabana', 'Bakabana', null, null, 'Ripe plantain slices dipped in batter and deep-fried, a popular snack.', 'Olgun muz dilimlerinin hamura bulanıp derin yağda kızartılmasıyla yapılan popüler bir atıştırmalıktır.', '', 4),
('740', 'Bara', 'Bara', null, null, 'A fried, spiced split-pea flour fritter, usually eaten with chutney.', 'Baharatlı bölünmüş bezelye ununun kızartılmasıyla yapılan, genellikle sosla yenen bir mücverdir.', '', 5),
('728', 'Kisra', 'Kisra', null, null, 'A thin fermented flatbread made from sorghum or millet flour, eaten with stews.', 'Sorgum veya darı unundan yapılan, yahnilerle yenen ince fermente bir yassı ekmektir.', '', 1),
('728', 'Asida', 'Asida', null, null, 'A thick, smooth porridge made from sorghum or wheat flour, served with a meat or vegetable sauce.', 'Sorgum veya buğday unundan yapılan, et veya sebze sosuyla servis edilen koyu ve pürüzsüz bir lapadır.', '', 2),
('728', 'Ful Medames', 'Ful Medames', null, null, 'Stewed and mashed fava beans seasoned with oil and spices, commonly eaten for breakfast.', 'Haşlanıp ezilen bakla fasulyesinin yağ ve baharatlarla tatlandırılıp genellikle kahvaltıda yenmesidir.', '', 3),
('729', 'Ful Medames', 'Ful Medames', null, null, 'Stewed and mashed fava beans seasoned with oil and spices, commonly eaten for breakfast.', 'Haşlanıp ezilen bakla fasulyesinin yağ ve baharatlarla tatlandırılıp genellikle kahvaltıda yenmesidir.', '', 1),
('729', 'Kisra', 'Kisra', null, null, 'A thin fermented flatbread made from sorghum flour, eaten with stews.', 'Sorgum unundan yapılan, yahnilerle yenen ince fermente bir yassı ekmektir.', '', 2),
('729', 'Asida', 'Asida', null, null, 'A thick, smooth porridge made from sorghum or wheat flour, served with a meat or okra sauce.', 'Sorgum veya buğday unundan yapılan, et veya bamya sosuyla servis edilen koyu ve pürüzsüz bir lapadır.', '', 3),
('729', 'Gurasa', 'Gurasa', null, null, 'A thick, round flatbread cooked on a griddle, often served with meat or okra stew.', 'Sacda pişirilen kalın ve yuvarlak bir ekmeğin genellikle et veya bamya yahnisiyle servis edilmesidir.', '', 4),
('729', 'Mullah', 'Mullah (Güveç)', null, null, 'A stew of meat, okra, or vegetables, typically ladled over kisra or asida.', 'Et, bamya veya sebzeden yapılan, genellikle kisra ya da asida üzerine dökülen bir yahnidir.', '', 5),
('144', 'Rice and Curry', 'Pirinç ve Köri', null, null, 'Steamed rice served with an assortment of spiced vegetable, meat, or fish curries.', 'Buharda pişmiş pirincin çeşitli baharatlı sebze, et veya balık körileriyle servis edilmesidir.', '', 1),
('144', 'Hoppers', 'Hoppers (Appa)', null, null, 'A bowl-shaped fermented rice-and-coconut-milk pancake, crisp at the edges and soft in the center.', 'Fermente pirinç ve hindistan cevizi sütünden yapılan, kenarları gevrek ortası yumuşak kase şekilli bir krepdir.', '', 2),
('144', 'Kottu Roti', 'Kottu Roti', null, null, 'Chopped flatbread stir-fried with egg, vegetables, and meat on a hot griddle.', 'Doğranmış yassı ekmeğin yumurta, sebze ve etle birlikte sıcak sacda kavrulmasıdır.', '', 3),
('144', 'Pol Sambol', 'Pol Sambol (Hindistan Cevizli Salata)', null, null, 'A spicy relish of grated coconut mixed with chili, lime, and onion.', 'Rendelenmiş hindistan cevizinin biber, limon ve soğanla karıştırıldığı acı bir salatadır.', '', 4),
('144', 'String Hoppers', 'İpliksi Hoppers (Idiyappam)', null, null, 'Steamed rice-flour noodles pressed into flat discs, served with curry or coconut sambol.', 'Pirinç ununun buharda pişirilip yassı disklere sıkıldığı, köri veya hindistan cevizli sosla servis edilen eriştedir.', '', 5),
('144', 'Lamprais', 'Lamprais', null, null, 'Rice cooked in meat stock, served with curries and accompaniments wrapped in a banana leaf and baked.', 'Et suyunda pişirilen pirincin köri ve garnitürlerle muz yaprağına sarılarak fırınlanmasıdır.', '', 6),
('144', 'Watalappan', 'Watalappan', null, null, 'A steamed custard pudding made with coconut milk, jaggery, and warm spices.', 'Hindistan cevizi sütü, hurma şekeri ve sıcak baharatlarla yapılan buharda pişmiş bir muhallebidir.', '', 7),
('144', 'Kiribath', 'Kiribath', null, null, 'Rice cooked with coconut milk until thick, cut into diamonds and served on festive occasions.', 'Pirincin hindistan cevizi sütüyle koyulaşana kadar pişirilip baklava dilimi şeklinde kesildiği bayramlık bir yemektir.', '', 8),
('724', 'Paella', 'Paella', 'Valencia', 'Valensiya', 'A saffron-flavored rice dish cooked with meat, seafood, or vegetables in a wide shallow pan.', 'Safranla tatlandırılan pirincin geniş sığ bir tavada et, deniz ürünü veya sebzeyle pişirilmesidir.', '', 1),
('724', 'Spanish Omelet', 'İspanyol Omleti (Tortilla Española)', null, null, 'A thick omelet of eggs, potatoes, and onion, fried and often served at room temperature.', 'Yumurta, patates ve soğandan yapılan kalın bir omletin kızartılıp genellikle oda sıcaklığında servis edilmesidir.', '', 2),
('724', 'Gazpacho', 'Gazpaço', null, null, 'A chilled soup of blended raw tomatoes, peppers, cucumber, and garlic.', 'Çiğ domates, biber, salatalık ve sarımsağın karıştırılmasıyla yapılan soğuk bir çorbadır.', '', 3),
('724', 'Iberian Ham', 'İber Jambonu', null, null, 'Dry-cured ham from free-range pigs, thinly sliced and prized for its rich, nutty flavor.', 'Serbest gezen domuzlardan elde edilen, ince dilimlenmiş, zengin ve kuruyemişimsi tada sahip kurutulmuş bir jambondur.', '', 4),
('724', 'Patatas Bravas', 'Patatas Bravas', null, null, 'Fried potato chunks topped with a spicy tomato sauce and often garlic mayonnaise.', 'Kızartılmış patates parçalarının acılı domates sosu ve genellikle sarımsaklı mayonezle servis edilmesidir.', '', 5),
('724', 'Churros', 'Churros', null, null, 'Deep-fried strips of choux dough, dusted with sugar and dipped in thick hot chocolate.', 'Şeker serpilmiş, kızartılmış dubruva hamuru şeritlerinin sıcak koyu çikolataya batırılarak yenmesidir.', '', 6),
('724', 'Croquetas', 'Kroket', null, null, 'Creamy béchamel filling, often with ham or chicken, breaded and deep-fried.', 'Genellikle jambon veya tavuklu kremamsı beşamel içinin galeta ununa bulanıp kızartılmasıdır.', '', 7),
('724', 'Pisto', 'Pisto', null, null, 'A stewed medley of tomatoes, peppers, onion, and zucchini, similar to ratatouille.', 'Domates, biber, soğan ve kabağın birlikte pişirildiği, ratatuiye benzeyen bir sebze yahnisidir.', '', 8),
('724', 'Fabada Asturiana', 'Fabada Asturiana', 'Asturias', 'Asturias', 'A hearty bean stew with white beans, chorizo, morcilla, and pork.', 'Beyaz fasulye, chorizo, kan sosisi ve domuz etinden yapılan doyurucu bir fasulye güvecidir.', '', 9),
('724', 'Galician-Style Octopus', 'Galiçya Usulü Ahtapot', 'Galicia', 'Galiçya', 'Boiled octopus sliced and seasoned with olive oil, paprika, and coarse salt.', 'Haşlanmış ahtapotun dilimlenip zeytinyağı, kırmızı biber ve kaba tuzla tatlandırılmasıdır.', '', 10),
('410', 'Kimchi', 'Kimçi', null, null, 'Fermented cabbage or radish seasoned with chili, garlic, and ginger.', 'Lahana veya turpun biber, sarımsak ve zencefille tatlandırılıp fermente edilmesidir.', '', 1),
('410', 'Bibimbap', 'Bibimbap', null, null, 'A bowl of rice topped with sautéed vegetables, meat, a fried egg, and chili paste, mixed together.', 'Pirincin üzerine kavrulmuş sebze, et, sahanda yumurta ve acı biber salçası eklenip karıştırılarak yenmesidir.', '', 2),
('410', 'Bulgogi', 'Bulgogi', null, null, 'Thin slices of marinated beef grilled or pan-fried until caramelized.', 'İnce dilimlenmiş marine edilmiş sığır etinin karamelize olana kadar ızgara veya tavada pişirilmesidir.', '', 3),
('410', 'Japchae', 'Japchae', null, null, 'Stir-fried glass noodles tossed with vegetables and beef in a sweet soy sauce.', 'Cam eriştenin sebze ve sığır etiyle tatlı bir soya sosunda kavrularak karıştırılmasıdır.', '', 4),
('410', 'Tteokbokki', 'Tteokbokki', null, null, 'Chewy rice cakes simmered in a spicy-sweet red chili sauce.', 'Çiğnenebilir pirinç keklerinin acı-tatlı kırmızı biber sosunda pişirilmesidir.', '', 5),
('410', 'Samgyeopsal', 'Samgyeopsal', null, null, 'Thick slices of pork belly grilled at the table and wrapped in lettuce leaves.', 'Kalın dilimlenmiş domuz göbeğinin masada ızgara edilip marul yaprağına sarılarak yenmesidir.', '', 6),
('410', 'Kimchi Jjigae', 'Kimçi Güveci', null, null, 'A hot stew of aged kimchi simmered with pork or tofu.', 'Olgunlaşmış kimçinin domuz eti veya tofu ile pişirildiği acı bir güveçtir.', '', 7),
('410', 'Naengmyeon', 'Naengmyeon (Soğuk Erişte)', null, null, 'Chewy buckwheat noodles served in a chilled, tangy broth or with spicy sauce.', 'Çiğnenebilir karabuğday eriştesinin soğuk ve ekşimsi bir suda veya acı sosla servis edilmesidir.', '', 8),
('410', 'Galbi', 'Galbi', null, null, 'Marinated beef short ribs grilled over an open flame.', 'Marine edilmiş sığır kaburgasının açık ateşte ızgara edilmesidir.', '', 9),
('410', 'Sundubu Jjigae', 'Sundubu Jjigae (Yumuşak Tofu Güveci)', null, null, 'A bubbling stew of soft tofu, seafood or meat, and chili in a spicy broth.', 'Yumuşak tofu, deniz ürünü veya et ve biberin acı bir çorbada kaynatıldığı bir güveçtir.', '', 10),
('710', 'Biltong', 'Biltong', null, null, 'Strips of dried, cured meat seasoned with vinegar and spices.', 'Sirke ve baharatlarla tatlandırılıp kurutulmuş şerit et parçalarıdır.', '', 1),
('710', 'Boerewors', 'Boerewors', null, null, 'A coiled sausage of spiced beef or pork, traditionally grilled over an open fire.', 'Baharatlı sığır veya domuz etinden yapılan sarmal bir sosisin geleneksel olarak açık ateşte ızgara edilmesidir.', '', 2),
('710', 'Bobotie', 'Bobotie', null, null, 'Spiced minced meat baked with dried fruit and topped with an egg custard.', 'Baharatlı kıymanın kuru meyveyle fırınlanıp üzerine yumurtalı bir kremayla kapatılmasıdır.', '', 3),
('710', 'Bunny Chow', 'Bunny Chow', 'Durban', 'Durban', 'A hollowed-out loaf of bread filled with spicy curry.', 'İçi oyulmuş bir ekmeğin acılı köri ile doldurulmasıdır.', '', 4),
('710', 'Chakalaka', 'Chakalaka', null, null, 'A spicy relish of tomatoes, onions, peppers, and beans, served as a side dish.', 'Domates, soğan, biber ve fasulyeden yapılan, yan yemek olarak servis edilen acı bir sostur.', '', 5),
('710', 'Potjiekos', 'Potjiekos', null, null, 'A slow-cooked stew of meat and vegetables simmered in a round cast-iron pot over a fire.', 'Et ve sebzelerin yuvarlak dökme demir bir tencerede ateş üzerinde yavaşça pişirildiği bir güveçtir.', '', 6),
('710', 'Pap', 'Pap (Mısır Lapası)', null, null, 'A stiff maize porridge, commonly eaten with a tomato-based sauce or grilled meat.', 'Genellikle domatesli bir sosla veya ızgara etle yenen sert bir mısır lapasıdır.', '', 7),
('706', 'Bariis Iskukaris', 'Bariis Iskukaris', null, null, 'Spiced rice cooked with raisins and vegetables, usually served alongside meat.', 'Kuru üzüm ve sebzeyle pişirilen baharatlı pirincin genellikle etle servis edilmesidir.', '', 1),
('706', 'Sambusa', 'Sambusa', null, null, 'A fried pastry triangle filled with spiced meat or vegetables.', 'Baharatlı et veya sebzeyle doldurulan üçgen şeklinde kızartılmış bir hamur işidir.', '', 2),
('706', 'Canjeero', 'Canjeero', null, null, 'A spongy fermented flatbread eaten for breakfast, similar to Ethiopian injera.', 'Etiyopya''nın injerasına benzeyen, kahvaltıda yenen süngerimsi fermente bir yassı ekmektir.', '', 3),
('706', 'Suqaar', 'Suqaar', null, null, 'Diced, sautéed meat cooked with onions, peppers, and spices.', 'Küçük doğranmış etin soğan, biber ve baharatlarla kavrulmasıdır.', '', 4),
('zz-somaliland', 'Canjeero', 'Canjeero', null, null, 'A spongy fermented flatbread eaten for breakfast, a staple across the Somali-speaking Horn of Africa.', 'Somalice konuşulan Afrika Boynuzu bölgesinde temel besin olan, kahvaltıda yenen süngerimsi fermente bir yassı ekmektir.', '', 1),
('zz-somaliland', 'Suqaar', 'Suqaar', null, null, 'Diced, sautéed meat cooked with onions, peppers, and spices.', 'Küçük doğranmış etin soğan, biber ve baharatlarla kavrulmasıdır.', '', 2),
('zz-somaliland', 'Bariis Iskukaris', 'Bariis Iskukaris', null, null, 'Spiced rice cooked with raisins and vegetables, usually served alongside meat.', 'Kuru üzüm ve sebzeyle pişirilen baharatlı pirincin genellikle etle servis edilmesidir.', '', 3),
('090', 'Kokoda', 'Kokoda', null, null, 'Raw fish marinated in lime juice and coconut milk with chopped vegetables.', 'Çiğ balığın limon suyu ve hindistan cevizi sütüyle doğranmış sebzelerle marine edilmesidir.', '', 1),
('090', 'Poi', 'Poi', null, null, 'A starchy paste made from pounded taro root, eaten as a staple.', 'Dövülmüş taro kökünden yapılan nişastalı bir ezme olup temel besin olarak tüketilir.', '', 2),
('090', 'Cassava Pudding', 'Maniyoka Pudingi', null, null, 'A dense, sweet pudding made from grated cassava, coconut milk, and sugar.', 'Rendelenmiş manyok, hindistan cevizi sütü ve şekerden yapılan yoğun ve tatlı bir pudingdir.', '', 3),
('703', 'Bryndzové Halušky', 'Bryndzové Halušky', null, null, 'Soft potato dumplings topped with sheep''s milk cheese and bits of bacon.', 'Yumuşak patates gnocchisinin koyun peyniri ve pastırma parçalarıyla süslenmesidir.', '', 1),
('703', 'Kapustnica', 'Kapustnica (Lahana Çorbası)', null, null, 'A sauerkraut soup cooked with smoked meat, sausage, and dried mushrooms.', 'Turşu lahananın füme et, sosis ve kuru mantarla pişirilmesiyle yapılan bir çorbadır.', '', 2),
('703', 'Sviečková', 'Sviečková', null, null, 'Slow-cooked beef in a creamy root vegetable sauce, served with bread dumplings.', 'Yavaş pişirilmiş sığır etinin kremamsı bir kök sebze sosunda, hamur köftesiyle servis edilmesidir.', '', 3),
('703', 'Trdelník', 'Trdelník', null, null, 'A sweet rolled dough wrapped around a spit, grilled, and coated in sugar and nuts.', 'Tatlı bir hamurun bir şişe sarılıp közlenerek şeker ve kuruyemişe bulanmasıdır.', '', 4),
('705', 'Potica', 'Potica', null, null, 'A rolled pastry filled with a sweet nut paste, typically walnuts.', 'Genellikle cevizden yapılan tatlı bir fındık ezmesiyle doldurulan rulo şeklinde bir hamur tatlısıdır.', '', 1),
('705', 'Jota', 'Jota', null, null, 'A hearty stew of sauerkraut, beans, and potatoes, often with smoked pork.', 'Turşu lahana, fasulye ve patatesten yapılan, genellikle füme domuz etli doyurucu bir güveçtir.', '', 2),
('705', 'Kranjska Klobasa', 'Kranjska Klobasa', 'Kranj', 'Kranj', 'A smoked pork sausage seasoned with garlic and pepper.', 'Sarımsak ve karabiberle tatlandırılan füme bir domuz sosisidir.', '', 3),
('705', 'Štruklji', 'Štruklji', null, null, 'Rolled dumpling dough filled with a sweet or savory filling, boiled or baked.', 'Tatlı veya tuzlu bir iç malzemeyle doldurulan rulo hamurun haşlanması veya fırınlanmasıdır.', '', 4),
('702', 'Hainanese Chicken Rice', 'Hainan Usulü Tavuklu Pilav', null, null, 'Poached chicken served with rice cooked in chicken fat and broth, plus chili and ginger sauces.', 'Haşlanmış tavuğun, tavuk yağı ve suyunda pişirilen pirinçle, biberli ve zencefilli soslarla servis edilmesidir.', '', 1),
('702', 'Laksa', 'Laksa', null, null, 'Rice noodles in a spicy coconut curry broth, topped with shrimp, tofu puffs, and bean sprouts.', 'Pirinç eriştesinin acılı hindistan cevizi köri çorbasında karides, tofu ve filizle servis edilmesidir.', '', 2),
('702', 'Chili Crab', 'Acılı Yengeç', null, null, 'Whole crab stir-fried in a thick, sweet-and-spicy tomato and chili sauce.', 'Bütün yengecin koyu, tatlı-acı bir domates ve biber sosunda kavrulmasıdır.', '', 3),
('702', 'Char Kway Teow', 'Char Kway Teow', null, null, 'Flat rice noodles stir-fried with prawns, egg, bean sprouts, and dark soy sauce.', 'Yassı pirinç eriştesinin karides, yumurta, filiz ve koyu soya sosuyla wokta kavrulmasıdır.', '', 4),
('702', 'Satay', 'Saten (Satay)', null, null, 'Grilled skewers of marinated meat served with a peanut dipping sauce.', 'Marine edilmiş etin şişe dizilerek ızgara yapılması ve yer fıstığı sosuyla servis edilmesidir.', '', 5),
('702', 'Bak Kut Teh', 'Bak Kut Teh', null, null, 'Pork ribs simmered in a fragrant broth of herbs and spices, often with garlic and dark soy.', 'Domuz kaburgasının otlar ve baharatlarla kokulu bir suda, genellikle sarımsak ve koyu soyayla pişirilmesidir.', '', 6),
('702', 'Roti Prata', 'Roti Prata', null, null, 'A flaky, pan-fried flatbread served with curry sauce for dipping.', 'Katmanlı, tavada kızartılmış bir yassı ekmeğin köri sosuna batırılarak yenmesidir.', '', 7),
('702', 'Kaya Toast', 'Kaya Toast', null, null, 'Toasted bread spread with coconut jam and butter, served with soft-boiled eggs.', 'Kızarmış ekmeğin hindistan cevizi reçeli ve tereyağıyla sürülüp az pişmiş yumurtayla servis edilmesidir.', '', 8),
('694', 'Cassava Leaf Stew', 'Maniyoka Yaprağı Güveci', null, null, 'Pounded cassava leaves stewed with meat or fish and palm oil.', 'Dövülmüş manyok yapraklarının et veya balık ve palmiye yağıyla pişirilmesidir.', '', 1),
('694', 'Jollof Rice', 'Jollof Pilavı', null, null, 'Rice cooked in a spiced tomato and pepper sauce with meat or vegetables.', 'Pirincin baharatlı domates ve biber sosunda et veya sebzeyle pişirilmesidir.', '', 2),
('694', 'Groundnut Soup', 'Yer Fıstığı Çorbası', null, null, 'A rich stew made from ground peanuts, tomatoes, and meat or fish.', 'Öğütülmüş yer fıstığı, domates ve et ya da balıktan yapılan zengin bir çorbadır.', '', 3),
('694', 'Fufu', 'Fufu', null, null, 'Pounded cassava or plantain formed into a smooth dough and eaten with soup.', 'Manyok veya muzun dövülerek pürüzsüz bir hamur haline getirilip çorbayla yenmesidir.', '', 4),
('690', 'Kari Zourit', 'Kari Zourit (Ahtapot Körisi)', null, null, 'Octopus simmered in a spiced coconut curry sauce.', 'Ahtapotun baharatlı hindistan cevizi köri sosunda pişirilmesidir.', '', 1),
('690', 'Grilled Fish Creole', 'Kreol Usulü Izgara Balık', null, null, 'Fresh fish marinated in herbs and spices, then grilled and served with a tomato-based Creole sauce.', 'Taze balığın ot ve baharatlarla marine edilip ızgara yapılarak domates bazlı bir Kreol sosuyla servis edilmesidir.', '', 2),
