('690', 'Bouyon Bred', 'Bouyon Bred (Sebze Güveci)', null, null, 'A light vegetable broth made from local leafy greens and root vegetables.', 'Yerel yeşil yapraklı sebzeler ve kök sebzelerden yapılan hafif bir sebze suyudur.', '', 4),
('688', 'Ćevapi', 'Ćevapi', null, null, 'Small grilled sausages of minced meat, served in a flatbread with onions and ajvar.', 'Kıymadan yapılan küçük ızgara sosislerin bir yassı ekmekte soğan ve ayvarla servis edilmesidir.', '', 1),
('688', 'Pljeskavica', 'Pljeskavica', null, null, 'A grilled patty of seasoned minced meat, served in bread with toppings and sauces.', 'Baharatlı kıymadan yapılan ızgara köftenin ekmekte garnitür ve soslarla servis edilmesidir.', '', 2),
('688', 'Sarma', 'Sarma', null, null, 'Cabbage leaves rolled around a filling of minced meat and rice, slow-cooked.', 'Lahana yapraklarının kıyma ve pirinç harcıyla sarılıp yavaşça pişirilmesidir.', '', 3),
('688', 'Karađorđeva Šnicla', 'Karađorđeva Şnitzel', null, null, 'A rolled and breaded veal or pork cutlet stuffed with cheese, deep-fried.', 'Peynirle doldurulan dana veya domuz etinin rulo yapılıp galeta ununa bulanarak kızartılmasıdır.', '', 4),
('688', 'Ajvar', 'Ayvar', null, null, 'A relish of roasted red peppers and eggplant blended with garlic and oil.', 'Közlenmiş kırmızı biber ve patlıcanın sarımsak ve yağla karıştırıldığı bir sostur.', '', 5),
('688', 'Burek', 'Börek', null, null, 'Layers of flaky pastry filled with minced meat, cheese, or spinach, baked in a coil.', 'Kıyma, peynir veya ıspanakla doldurulan katmanlı bir hamurun sarmal şekilde fırınlanmasıdır.', '', 6),
('688', 'Gibanica', 'Gibanica', null, null, 'A baked pastry of filo layers filled with cheese and eggs.', 'Peynir ve yumurtayla doldurulan yufka katlarının fırınlanmasıdır.', '', 7),
('686', 'Thieboudienne', 'Thieboudienne (Balıklı Pirinç)', null, null, 'Fish and rice cooked together with tomato sauce and vegetables, widely regarded as Senegal''s national dish.', 'Balık ve pirincin domates sosu ve sebzelerle birlikte pişirildiği, Senegal''in milli yemeği sayılan bir yemektir.', '', 1),
('686', 'Yassa', 'Yassa (Soğanlı Limonlu Tavuk)', null, null, 'Chicken marinated in lemon and onions, then grilled or braised in the tangy marinade.', 'Limon ve soğanla marine edilen tavuğun ekşimsi marinasında ızgara veya güveç olarak pişirilmesidir.', '', 2),
('686', 'Mafé', 'Mafe', null, null, 'A stew of meat simmered in a rich peanut sauce with vegetables.', 'Etin sebzelerle birlikte zengin bir yer fıstığı sosunda pişirildiği bir güveçtir.', '', 3),
('686', 'Accara', 'Accara (Fasulye Köftesi)', null, null, 'Deep-fried fritters made from ground black-eyed peas, seasoned with onion and chili.', 'Öğütülmüş börülcenin soğan ve biberle tatlandırılıp kızartılmasıyla yapılan köftelerdir.', '', 4),
('686', 'Thiakry', 'Thiakry', null, null, 'A sweet dessert of steamed millet couscous mixed with yogurt, cream, and vanilla.', 'Buharda pişirilmiş darı kuskusunun yoğurt, krema ve vanilyayla karıştırıldığı tatlı bir tatlıdır.', '', 5),
('682', 'Kabsa', 'Kabsa', null, null, 'Spiced rice cooked with meat, tomatoes, and a blend of aromatic spices.', 'Baharatlı pirincin et, domates ve aromatik baharat karışımıyla pişirilmesidir.', '', 1),
('682', 'Mandi', 'Mandi', null, null, 'Meat slow-cooked in a pit oven and served over spiced, smoky rice.', 'Etin bir çukur fırında yavaşça pişirilip baharatlı ve dumanlı pirincin üzerine konularak servis edilmesidir.', '', 2),
('682', 'Jareesh', 'Cerîş', null, null, 'Crushed wheat porridge cooked with meat and mild spices until creamy.', 'Kırılmış buğdayın et ve hafif baharatlarla kremamsı bir kıvama gelene kadar pişirilmesidir.', '', 3),
('682', 'Saleeg', 'Salig', null, null, 'Rice cooked in milk and chicken broth until creamy, topped with tender chicken.', 'Pirincin süt ve tavuk suyunda kremamsı bir kıvama gelene kadar pişirilip üzerine yumuşak tavuk konulmasıdır.', '', 4),
('682', 'Harees', 'Harise', null, null, 'Wheat and meat pounded together and slow-cooked into a thick, smooth porridge.', 'Buğday ve etin birlikte dövülüp yavaşça pişirilerek koyu ve pürüzsüz bir lapaya dönüştürülmesidir.', '', 5),
('682', 'Mutabbaq', 'Mutabbak', null, null, 'A folded, pan-fried pastry filled with spiced minced meat, egg, and onion.', 'Baharatlı kıyma, yumurta ve soğanla doldurulan katlanmış bir hamurun tavada kızartılmasıdır.', '', 6),
('678', 'Calulu', 'Calulu', null, null, 'A stew of dried fish or smoked meat cooked with okra, eggplant and palm oil, usually served with rice or fufu.', 'Kurutulmuş balık veya tütsülenmiş etin bamya, patlıcan ve palmiye yağıyla pişirildiği, genellikle pilav veya fufu ile servis edilen bir güveç.', '', 1),
('678', 'Feijoada de São Tomé', 'Feijoada de São Tomé', null, null, 'A hearty bean stew cooked with smoked meats, sausage and vegetables.', 'Tütsülenmiş et, sosis ve sebzelerle pişirilen doyurucu bir fasulye güveci.', '', 2),
('678', 'Fried plantain', 'Kızarmış muz', null, null, 'Ripe plantains sliced and fried until caramelized, served as a side dish.', 'Karamelize olana kadar dilimlenip kızartılan olgun muz, yan yemek olarak servis edilir.', '', 3),
('674', 'Nidi di rondine', 'Nidi di rondine', null, null, 'Rolled pasta "swallow''s nests" filled with ham and cheese, baked in a creamy béchamel sauce.', 'Jambon ve peynirle doldurulup kremalı beşamel sosla fırınlanan rulo makarna "kırlangıç yuvaları".', '', 1),
('674', 'Fagioli con le cotiche', 'Fagioli con le cotiche', null, null, 'A stew of beans simmered with pork rind.', 'Domuz derisiyle pişirilen fasulye güveci.', '', 2),
('674', 'Torta Tre Monti', 'Torta Tre Monti', null, null, 'A layered wafer cake filled with hazelnut cream and coated in chocolate.', 'Fındık kremasıyla katmanlanmış ve çikolatayla kaplanmış gofret pasta.', '', 3),
('882', 'Palusami', 'Palusami', null, null, 'Coconut cream baked inside parcels of taro leaves.', 'Taro yapraklarının içine sarılıp pişirilen hindistancevizi kreması.', '', 1),
('882', 'Oka', 'Oka', null, null, 'Raw fish marinated in lime juice and coconut cream, similar to ceviche.', 'Misket limonu suyu ve hindistancevizi kremasında marine edilmiş çiğ balık, seviçeye benzer.', '', 2),
('882', 'Sapasui', 'Sapasui', null, null, 'A Samoan-style stir-fried noodle dish with meat and vegetables, adapted from Chinese chop suey.', 'Çin usulü chop suey''den uyarlanan, et ve sebzelerle hazırlanan Samoa usulü kızartılmış erişte yemeği.', '', 3),
('882', 'Fa''ausi', 'Fa''ausi', null, null, 'Grated taro or tapioca served with a sweet caramelized coconut sauce.', 'Rendelenmiş taro veya tapyokanın tatlı, karamelize hindistancevizi sosuyla servis edilmesi.', '', 4),
('670', 'Roasted breadfruit and fried jackfish', 'Kızarmış ekmek meyvesi ve kızartılmış jack balığı', null, null, 'The national dish: breadfruit roasted over an open fire, served with fried jackfish.', 'Ulusal yemek: açık ateşte kızartılan ekmek meyvesinin, kızartılmış jack balığıyla servis edilmesi.', '', 1),
('670', 'Souse', 'Souse', null, null, 'A pickled dish of boiled pork or chicken feet marinated with lime, cucumber and hot pepper.', 'Haşlanmış domuz veya tavuk ayaklarının misket limonu, salatalık ve acı biberle marine edildiği turşu tarzı bir yemek.', '', 2),
('670', 'Callaloo soup', 'Callaloo çorbası', null, null, 'A soup made from callaloo leaves, okra and coconut milk, often with crab or meat.', 'Callaloo yaprakları, bamya ve hindistancevizi sütüyle yapılan, genellikle yengeç veya et içeren bir çorba.', '', 3),
('662', 'Green fig and saltfish', 'Yeşil muz ve tuzlu balık', null, null, 'Saint Lucia''s national dish: boiled green bananas served with sautéed salted cod.', 'Saint Lucia''nın ulusal yemeği: haşlanmış yeşil muzun, sote edilmiş tuzlu morina balığıyla servis edilmesi.', '', 1),
('662', 'Bouyon', 'Bouyon', null, null, 'A hearty one-pot stew of meat, dumplings, and root vegetables.', 'Et, hamur topları ve kök sebzelerden oluşan doyurucu, tek tencerede pişen bir güveç.', '', 2),
('662', 'Accras', 'Accras', null, null, 'Deep-fried fritters made from salted codfish batter.', 'Tuzlu morina balığı hamurundan yapılan derin yağda kızartılmış köfteler.', '', 3),
('659', 'Stewed saltfish with spicy plantains', 'Güveçte tuzlu balık ve baharatlı muz', null, null, 'The national dish: stewed salted cod served with spiced plantains, coconut dumplings and breadfruit.', 'Ulusal yemek: baharatlı muz, hindistancevizi hamur topları ve ekmek meyvesiyle servis edilen güveçte tuzlu morina balığı.', '', 1),
('659', 'Goat water', 'Keçi suyu', null, null, 'A thick, spiced stew made from goat meat, traditionally served at festive occasions.', 'Keçi etinden yapılan, geleneksel olarak bayram ve kutlamalarda servis edilen koyu kıvamlı, baharatlı bir güveç.', '', 2),
